  ", bukan pengukuran instrumen: ketelitiannya bergantung pada benda acuan yang benar-benar sebidang dengan batang dan foto yang tegak lurus. Angka yang dihasilkan": "، وليس قياسًا بجهاز: تعتمد دقّته على جسم مرجعي يقع فعلًا في مستوى الجذع نفسه، وعلى صورة ملتقطة بشكل عمودي. والرقم الناتج",
  ", tombol batalnya ada di halaman ini. Setelah ditinjau, kami menahan jejak keputusannya — penghapusan diminta lewat surel:": "، فزر الإلغاء موجود في هذه الصفحة. وبعد المراجعة نحتفظ بأثر القرار — ويُطلب الحذف عبر البريد:",
  ". Ia tidak menjadi kredit karbon, tidak masuk registri mana pun, dan tidak dipakai menyatakan siapa pun netral karbon.": ". ولا يتحوّل إلى رصيد كربوني، ولا يدخل أي سجل، ولا يُستخدم لإعلان أي جهة محايدة كربونيًا.",
  ". Kalau Anda belum punya lahan terdaftar, alat itu belum bisa Anda buka sendiri — itu keadaan sekarang, bukan janji. Isi pendaftaran di bawah dan tim Glyiv yang mengatur akses serta cara pengukurannya bersama Anda.": ". إن لم تكن لديك أرض مسجّلة بعد، فلن تتمكّن من فتح تلك الأداة بنفسك — هذا هو الوضع اليوم، وليس وعدًا. املأ التسجيل أدناه وسيتولّى فريق Glyiv ترتيب الوصول وطريقة القياس معك.",
  "+ Daftarkan lahan": "+ سجّل أرضًا",
  "+ Daftarkan outlet": "+ سجّل منفذًا",
