  "Anda boleh berhenti kapan saja.": "يمكنك التوقّف في أي وقت.",
  "Anda memotret batang bersama benda berukuran diketahui di bidang yang sama (penggaris 30 cm, kertas A4, atau orang setinggi ±170 cm), lalu menandai empat titik di layar. Skalanya dihitung dari benda acuan itu. Jalan di HP dan tablet mana pun, tanpa memasang apa pun. Alatnya ada di katalog pohon sebuah lahan di dalam konsol Glyiv.": "تصوّر الجذع مع جسم معلوم الحجم في المستوى نفسه (مسطرة 30 سم، أو ورقة A4، أو شخص بطول ±170 سم)، ثم تحدّد أربع نقاط على الشاشة. ويُحسب المقياس من ذلك الجسم المرجعي. يعمل على أي هاتف أو جهاز لوحي دون تثبيت أي شيء. والأداة موجودة في كتالوج الأشجار لأرضٍ داخل لوحة Glyiv.",
