  "Belum ada berkas APK yang bisa diunduh, dan kami tidak akan menaruh tautan unduhan sebelum aplikasinya benar-benar ada. Jangan menunggu tautan itu untuk mulai.": "لا يوجد ملف APK للتنزيل بعد، ولن نضع رابط تنزيل قبل أن يوجد التطبيق فعلًا. لا تنتظر ذلك الرابط لتبدأ.",
