  "Cukup sejelas yang bisa Anda tunjukkan di lapangan. Titik pastinya disepakati bersama tim nanti.": "بوضوح يكفي لتتمكّن من الإشارة إليه في الميدان. أما النقطة الدقيقة فيُتّفق عليها مع الفريق لاحقًا.",
  "Daftar untuk ikut mengukur pohon di lapangan — keliling batang (DBH), tinggi, dan jenisnya — lalu tim Glyiv menghubungi Anda.": "سجّل للمشاركة في قياس الأشجار ميدانيًا — محيط الجذع (DBH)، والارتفاع، والنوع — ثم يتواصل معك فريق Glyiv.",
  "dan terbaca oleh tim Glyiv — bukan oleh pengguna lain. Yang tersimpan adalah isian formulir ini (nama, kontak, nama daerah, pengalaman) ditambah penanda area daftar pantauan bila Anda memilih salah satu. Tidak ada berkas, tidak ada koordinat, tidak ada nomor identitas — batas area yang Anda gambar tetap tertutup untuk tim Glyiv.": "ويقرأها فريق Glyiv — لا المستخدمون الآخرون. والمخزَّن هو محتوى هذا النموذج (الاسم، وجهة الاتصال، واسم المنطقة، والخبرة) إضافةً إلى مؤشّر لمنطقة قائمة المتابعة إن اخترت واحدة. لا ملفات، ولا إحداثيات، ولا أرقام هوية — وحدود المنطقة التي ترسمها تبقى مغلقة أمام فريق Glyiv.",
