  "Punya lahan hutan, mangrove, agroforestri, atau lahan produktif? Daftarkan lahannya, tim Glyiv memetakan batasnya, lalu pertumbuhannya dipantau dan kontribusinya tercatat.": "هل لديك أرض غابات أو مانغروف أو زراعة حرجية أو أرض منتجة؟ سجّل الأرض، ويرسم فريق Glyiv حدودها، ثم يُراقَب نموّها وتُسجَّل مساهمتها.",
  "Rawat": "اعتنِ",
  "Ringan — Olahraga ringan 1–3 hari seminggu. Pengali 1,375×.": "خفيف — تمارين خفيفة 1–3 أيام أسبوعيًا. المعامل 1.375×.",
