  "Satu akun Glyiv untuk seluruh ekosistem. Pilih cabang di sidebar kiri, atau mulai dari kartu di bawah.": "حساب Glyiv واحد للمنظومة كاملة. اختر فرعًا من الشريط الجانبي، أو ابدأ من البطاقات أدناه.",
  "Satu akun, seluruh cabang. Yang bertanda “peta jalan” belum dibangun — kami mengatakannya apa adanya.": "حساب واحد لكل الفروع. وما يحمل وسم «خارطة طريق» لم يُبنَ بعد — ونقول ذلك صراحةً.",
  "Satu saja, yang benar-benar Anda pakai. Hanya terbaca tim Glyiv; tidak ditampilkan ke pengguna lain.": "واحدة فقط، تلك التي تستخدمها فعلًا. يقرأها فريق Glyiv وحده؛ ولا تُعرض للمستخدمين الآخرين.",
  "sebelum berarti apa-apa. Sertifikasi, MRV, dan pendaftaran registri masih peta jalan Glyiv — bukan kemampuan yang sudah jalan.": "قبل أن يعني شيئًا. فالاعتماد وMRV والتسجيل في السجلات ما زالت في خارطة طريق Glyiv — وليست قدرة تعمل بالفعل.",
