  "— angkanya dihitung dari pustaka faktor emisi Glyiv, dan batasnya ditulis di halamannya sendiri.": "— تُحسب الأرقام من مكتبة معاملات الانبعاث لدى Glyiv، وحدودها مكتوبة في صفحتها الخاصة.",
  "— bukan sedang ditinjau, bukan sedang menunggu persetujuan. Karena itu berkas APK-nya kami sediakan langsung di sini.": "— ليس قيد المراجعة، ولا في انتظار موافقة. لذلك نوفّر ملف APK هنا مباشرة.",
  "— tetapi pemasangan dan pembukaan pertamanya tetap butuh koneksi.": "— لكن التثبيت وأول فتح ما زالا يحتاجان اتصالًا.",
  "— tidak berguna di luar jaringan itu.": "— لا فائدة منه خارج تلك الشبكة.",
  "— tombol di sebelahnya, tanpa memasang apa pun.": "— الزر المجاور له، دون تثبيت أي شيء.",
  ", berkas itu bukan milik kami — jangan dipasang.": "، فهذا الملف ليس ملكنا — لا تثبّته.",
  ", bukan kunci rilis Glyiv. Sidik jari sertifikatnya, sama untuk keenamnya:": "، وليس مفتاح إصدار من Glyiv. بصمة الشهادة، وهي نفسها للستة جميعًا:",
  ", bukan menyalinnya ke dalam berkas. Tampilan dan datanya dimuat dari server Glyiv saat aplikasi dibuka — jadi yang ada di dalam APK hanyalah pembungkusnya: ikon, nama, dan kode yang membuka jendela. Itulah alasan 20–29 KB, dan itu bukan tanda berkasnya rusak atau kosong.": "، لا نسخه داخل الملف. تُحمَّل الواجهة وبياناتها من خوادم Glyiv عند فتح التطبيق — فما في ملف APK ليس إلا الغلاف: أيقونة واسم وشيفرة تفتح النافذة. ولهذا حجمه 20–29 KB، وليس ذلك دليلًا على أن الملف تالف أو فارغ.",
  ", bukan oleh petugas harian.": "، لا من قِبل الموظفين اليوميين.",
  ", dan aplikasi ini tidak menawarkan apa pun yang tidak bisa Anda dapat dari versi webnya. Yang ia tambahkan adalah ikon di layar utama, tampilan layar penuh tanpa bilah alamat, dan — khusus Glyiv Kabar — widget layar utama.": "، ولا يقدّم هذا التطبيق شيئًا لا تجده في نسخته على الويب. ما يضيفه هو أيقونة على الشاشة الرئيسية، وعرض بملء الشاشة دون شريط عنوان، و— في Glyiv News وحده — أداة على الشاشة الرئيسية.",
  ", disediakan supaya aplikasinya bisa dicoba di perangkat sungguhan sebelum masuk toko resmi. Ia bukan produk bersertifikat, tidak diperiksa Google Play Protect sebelum diunggah, dan tidak menerima pembaruan otomatis. Penerbitan di Play Store — termasuk penandatanganan dengan kunci rilis — masih": "، متاح ليُجرَّب التطبيق على جهاز حقيقي قبل وصوله إلى متجر رسمي. وهو ليس منتجًا معتمدًا، ولم يفحصه Google Play Protect قبل الرفع، ولا يتلقّى تحديثات تلقائية. أما النشر على Play Store — بما فيه التوقيع بمفتاح إصدار — فما زال",
  ": pasang aplikasi penghitung hash dari Play Store, atau lewat Termux:": ": ثبّت تطبيق حساب البصمة من Play Store، أو استخدم Termux:",
  ". Aplikasi untuk iOS belum ada; untuk sekarang pengguna iPhone dan iPad memakai versi webnya, yang bisa ditambahkan ke layar utama lewat menu Bagikan di Safari.": ". لا يوجد تطبيق iOS بعد؛ ويستخدم مستخدمو iPhone و iPad حاليًا نسخة الويب، ويمكن إضافتها إلى الشاشة الرئيسية من قائمة المشاركة في Safari.",
  ". Izin ini melekat pada aplikasi yang Anda pakai membuka berkasnya (Chrome, Files, atau Drive) —": ". يرتبط هذا الإذن بالتطبيق الذي تفتح به الملف (Chrome أو Files أو Drive) —",
