  "Keduanya menghubungi server lokal di dalam outlet, bukan internet. Kalau ponsel Anda tidak berada di jaringan yang sama, layarnya akan berhenti di “tidak dapat terhubung” — itu perilaku yang benar, bukan kerusakan.": "كلاهما يتصل بخادم محلي داخل المنفذ، لا بالإنترنت. وإن لم يكن هاتفك على الشبكة نفسها فستتوقف الشاشة عند «تعذّر الاتصال» — وهذا سلوك صحيح، لا عطل.",
  "Keenam berkasnya sudah selesai dibangun dan sidik jari SHA-256-nya sudah tercantum di kartu masing-masing, tetapi berkasnya belum diunggah ke tempat yang bisa diakses umum. Begitu tautannya dipasang, tombolnya menyala sendiri dan pita ini berganti.": "الملفات الستة جاهزة وبصمات SHA-256 الخاصة بها مدرجة على بطاقاتها، لكنها لم تُرفع بعد إلى مكان متاح للعموم. وبمجرد وضع الروابط تُضاء الأزرار تلقائيًا ويتغيّر هذا الشريط.",
