  "Perusahaan induk teknologi asal Indonesia. Kami membangun produk bernilai tinggi untuk masalah yang penting — dimulai dari": "شركة تقنية إندونيسية أم. نبني منتجات عالية القيمة لمشكلات مهمة — بدءًا من",
  "peta jalan": "خارطة طريق",
  "Platform intelijen hijau kelas enterprise: agen AI yang membaca data karbon perusahaan, menganalisis emisi terhadap biaya, lalu mengubahnya jadi keputusan. Lacak, hitung, offset — selaras GHG Protocol dan ISO 14064. Sertifikasi dan registri masih peta jalan, bukan kemampuan yang sudah jadi.": "منصة ذكاء أخضر بمستوى المؤسسات: وكيل ذكاء اصطناعي يقرأ بيانات الكربون لدى الشركة، ويحلّل الانبعاثات مقابل التكلفة، ثم يحوّلها إلى قرارات. تتبَّع، واحسب، وعوّض — بما يتوافق مع GHG Protocol و ISO 14064. أما الاعتماد والسجلات فما زالا خارطة طريق، لا قدرة مكتملة.",
  "Play Protect mungkin memperingatkan karena pemasangnya bukan Play Store. Itu wajar untuk berkas dari luar toko — pastikan SHA-256-nya cocok sebelum melanjutkan.": "قد يحذّرك Play Protect لأن المثبِّت ليس Play Store. وهذا طبيعي لملف من خارج المتجر — تأكّد من تطابق SHA-256 قبل المتابعة.",
