  "Sebelum memasang, cocokkan SHA-256 berkas yang Anda unduh dengan angka di kartunya — caranya ada di bagian bawah halaman. Dan baca dulu tiga hal yang perlu diketahui sebelum memasang berkas dari luar Play Store.": "قبل التثبيت، قارن بصمة SHA-256 للملف الذي نزّلته بالرقم المكتوب على بطاقته — والطريقة في أسفل الصفحة. واقرأ أولًا الأمور الثلاثة التي يجدر معرفتها قبل تثبيت ملف من خارج Play Store.",
