  "— belum ada satu pun efek yang sudah berjalan.": "— ولا أثر واحد منها يعمل حتى الآن.",
  ", bukan hasil pengukuran tersertifikasi: nilai NDVI dan jenis tegakan yang dipakai estimasi itu ditetapkan peninjau Glyiv secara manual, belum ditarik dari citra satelit. Pemantauan satelit berkala, sertifikasi, MRV, dan registri karbon masih berada di peta jalan dan belum berjalan.": "، وليس قياسًا معتمدًا: قيمة NDVI ونوع الغطاء الشجري المستخدمان في هذا التقدير يحدّدهما مراجع من Glyiv يدويًا، ولم تُسحب بعد من صور الأقمار الصناعية. المراقبة الدورية بالأقمار الصناعية والاعتماد وMRV وسجل الكربون كلها ما زالت على خارطة طريق ولم تبدأ بعد.",
  ". Pemilik yang menyetujui permintaan Anda.": "‏. المالك هو من يوافق على طلبك.",
  ". Yang masih ditunggu adalah jawaban sesi dari server — isi halaman muncul begitu jawabannya datang.": "‏. ما ينتظره النظام هو ردّ الجلسة من الخادم — ويظهر محتوى الصفحة فور وصول الرد.",
  "200 transaksi pertama tiap bulan gratis, dan tagihan pemakaian tidak pernah melewati Rp300.000 per bulan berapa pun jumlah transaksinya.": "أول 200 معاملة في كل شهر مجانية، ولا تتجاوز فاتورة الاستخدام Rp300.000 شهريًا مهما بلغ عدد المعاملات.",
