  "Alamat / keterangan lokasi lahan": "العنوان / وصف موقع الأرض",
  "Alamat outlet terisi otomatis dari nama di atas.": "يُملأ عنوان المنفذ تلقائيًا من الاسم أعلاه.",
  "Alternatif dari bayar per transaksi, mencakup modul yang Anda nyalakan.": "بديل عن الدفع لكل معاملة، ويشمل الوحدات التي تُفعّلها.",
  "Apa pun yang menurut Anda perlu diketahui peninjau — akses jalan, sengketa batas, atau kondisi tegakan saat ini.": "أي شيء ترى أن على المراجع معرفته — الوصول بالطريق، أو نزاعات الحدود، أو حالة الغطاء الشجري الآن.",
  "Atau tautan sertifikat": "أو رابط الشهادة",
  "Baru mulai memantau. Gambar satu area dan siram pohon pertama Anda.": "بدأت المتابعة للتو. ارسم منطقة واحدة واسقِ شجرتك الأولى.",
  "Bayar per transaksi": "الدفع لكل معاملة",
  "begitu didaftarkan. Tim Glyiv meninjau pendaftarannya setelah itu — peninjauan tidak menghentikan uji coba, tetapi Glyiv berhak menghentikan layanan bila outlet dipakai di luar ketentuan. Angka karbon yang dihasilkan sistem ini": "فور تسجيله. يراجع فريق Glyiv التسجيل بعد ذلك — والمراجعة لا توقف الفترة التجريبية، لكن يحق لـ Glyiv إيقاف الخدمة إذا استُخدم المنفذ خارج الشروط. أرقام الكربون التي ينتجها هذا النظام",
  "Bekerja di outlet yang sudah terdaftar? Masukkan alamat outletnya — tercetak di stiker QR meja, mis.": "هل تعمل في منفذ مسجَّل بالفعل؟ أدخل عنوان المنفذ — وهو مطبوع على ملصق QR الطاولة، مثل",
  "Belum ada Green Asset terdaftar": "لا توجد أصول خضراء مسجَّلة بعد",
  "Belum ada outlet": "لا يوجد منفذ بعد",
  "Berkas PDF tidak bisa dikecilkan otomatis, jadi PDF harus di bawah 5 MB. Format: JPG, PNG, WebP, atau PDF.": "لا يمكن تصغير ملفات PDF تلقائيًا، لذا يجب أن يكون ملف PDF أقل من 5 MB. الصيغ: JPG أو PNG أو WebP أو PDF.",
  "Berkas terkirim ke arsip Glyiv begitu Anda memilihnya — juga kalau pengajuan ini akhirnya tidak jadi Anda kirim. Isinya hanya dipakai tim peninjau Glyiv, tidak pernah ditampilkan di marketplace maupun ke penyewa. Penghapusan dari arsip hanya bisa diminta ke admin.": "يُرسل الملف إلى أرشيف Glyiv لحظة اختياره — حتى لو لم ترسل هذا الطلب في النهاية. ولا يستخدم محتواه سوى فريق المراجعة في Glyiv، ولا يُعرض في السوق ولا للمستأجر. ولا يمكن طلب حذفه من الأرشيف إلا من المشرف.",
  "Berkasnya dibuka terbatas: Anda dan tim peninjau Glyiv. Tidak ditampilkan di marketplace, tidak diberikan ke penyewa atau pembeli. Yang kami janjikan adalah pemakaian terbatas itu — bukan jaminan teknis bahwa salinannya mustahil tersebar setelah ditinjau.": "الوصول إلى الملف محدود: أنت وفريق المراجعة في Glyiv. ولا يُعرض في السوق ولا يُسلَّم لمستأجر أو مشترٍ. ما نعد به هو هذا الاستخدام المحدود — لا ضمان تقني بأن نسخة منه لا يمكن أن تنتشر بعد المراجعة.",
  "Berkasnya sedang diperbarui — sidik SHA-256 di bawah belum cocok dengan yang Anda unduh hari ini.": "يجري تحديث الملفات — وبصمات SHA-256 أدناه لا تطابق بعد ما تنزّله اليوم.",
  "bersifat indikatif dan disepakati per outlet — bukan penawaran final; rinciannya dan pilihan modulnya Anda setujui di langkah berikutnya.": "إرشادية ويُتفق عليها لكل منفذ — وليست عرضًا نهائيًا؛ وتوافق على التفاصيل واختيار الوحدات في الخطوة التالية.",
  "Biaya setelah masa uji coba": "التكلفة بعد الفترة التجريبية",
  "boleh — dikecilkan dulu di perangkat Anda sebelum dikirim, dan hasil akhirnya paling besar": "مقبولة — إذ تُصغَّر على جهازك قبل الإرسال، ولا تتجاوز النتيجة النهائية",
  "Buka daftar pantauan": "افتح قائمة المتابعة",
  "Buka dasbor imbalan": "افتح لوحة المكافأة",
  "Catatan imbalan lahan Anda dibaca dari buku besar Glyiv dan tidak diulang di halaman ini, supaya tidak pernah ada dua angka yang bisa berbeda.": "تُقرأ سجلات مكافأة أرضك من دفتر Glyiv ولا تتكرر في هذه الصفحة، حتى لا يوجد أبدًا رقمان قد يختلفان.",
  "Catatan tambahan": "ملاحظات إضافية",
  "Contoh: 82 m² = 0,0082 ha. Angka ini perkiraan Anda; luas resmi dihitung ulang dari batas peta saat pengajuan disetujui. Tanpa angka ini peninjau tidak punya pembanding untuk hasil hitungannya.": "مثال: 82 m² = 0.0082 ha. هذا الرقم تقديرك أنت؛ وتُعاد الحسبة الرسمية للمساحة من حدود الخريطة عند الموافقة على الطلب. وبدونه لا يملك المراجع ما يقارن به نتيجة حسابه.",
  "Cukup alamat atau patokan yang bisa dikenali tim peninjau. Batas lahan yang dipakai sistem digambar admin dari peta saat peninjauan, bukan dari teks ini.": "يكفي عنوان أو معلَم يمكن لفريق المراجعة التعرف عليه. أما حدود الأرض التي يستخدمها النظام فيرسمها المشرف من الخريطة أثناء المراجعة، لا من هذا النص.",
  "Daftar & mulai uji coba": "سجّل وابدأ الفترة التجريبية",
