  "di arsip terkunci Glyiv, jadi angka pada foto itu tetap terbaca oleh tim peninjau — memang itu yang diperiksa. Fotonya hanya bisa dihapus admin Glyiv, tidak oleh Anda sendiri.": "في أرشيف Glyiv المقفل، لتبقى الأرقام في تلك الصورة مقروءة لفريق المراجعة — فذلك بالضبط ما يُفحص. ولا يمكن حذف الصورة إلا من مشرف Glyiv، لا منك.",
  "di bawah dan outlet Anda langsung hidup dengan masa uji coba": "أدناه ويعمل منفذك فورًا بفترة تجريبية مدتها",
