  "Foto KTP (wajib)": "صورة بطاقة الهوية KTP (إلزامية)",
  "Foto KTP, swafoto, dan sertifikat dipakai tim peninjau Glyiv untuk satu hal saja: memastikan pengaju adalah orang yang berhak atas lahan itu.": "يستخدم فريق المراجعة في Glyiv صورة بطاقة KTP والصورة الشخصية والشهادة لغرض واحد فقط: التأكد من أن مقدّم الطلب هو صاحب الحق في تلك الأرض.",
  "Foto sampai": "الصور حتى",
  "Glyiv GIP Outlet mencatat transaksi harian outlet Anda dan menghitung jejak karbon tiap menu dari resepnya — terlacak sampai ke bahannya, dan asal setiap angka selalu disebutkan.": "يسجّل Glyiv GIP Outlet معاملات منفذك اليومية ويحسب البصمة الكربونية لكل صنف في القائمة من وصفته — متتبَّعة حتى المكوّن، مع ذكر مصدر كل رقم دائمًا.",
  "Green Assets adalah lahan hijau Anda — lahan pohon atau lahan produktif — yang didaftarkan ke Glyiv supaya batas, luas, dan estimasi serapannya tercatat dalam satu berkas yang bisa ditelusuri. Daftarkan lahan pertama Anda, lalu tim Glyiv meninjaunya sebelum lahan itu aktif.": "الأصول الخضراء هي أرضك الخضراء — أرض أشجار أو أرض منتجة — تُسجَّل لدى Glyiv لتُدوَّن حدودها ومساحتها وتقدير امتصاصها في ملف واحد قابل للتتبع. سجّل أرضك الأولى، ثم يراجعها فريق Glyiv قبل أن تصبح فعّالة.",
  "Hanya terbaca Anda dan tim Glyiv. Tidak ditampilkan ke pelanggan.": "لا يقرؤه سواك وفريق Glyiv. ولا يُعرض للعملاء.",
