  "Imbalan Anda": "مكافأتك",
  "Isi data lahan dan bukti kepemilikannya. Tim peninjau Glyiv memeriksanya satu per satu — untuk lahan, bukti kepemilikan memang syarat, bukan formalitas.": "املأ بيانات الأرض وإثبات ملكيتها. يفحصها فريق المراجعة في Glyiv واحدًا واحدًا — فإثبات الملكية للأرض شرط فعلي لا إجراء شكلي.",
  "Jenis lahan": "نوع الأرض",
  "Jenis lahan yang Anda pilih menentukan ke jalur mana pengajuan ini diarahkan, bukan status akhirnya. Klasifikasi final ditetapkan tim peninjau saat lahan ditinjau, dan jalur bursa komoditas masih ada di peta jalan Glyiv — belum berjalan hari ini.": "نوع الأرض الذي تختاره يحدد المسار الذي يُوجَّه إليه هذا الطلب، لا حالته النهائية. أما التصنيف النهائي فيحدده فريق المراجعة عند مراجعة الأرض، ومسار بورصة السلع ما زال على خارطة طريق Glyiv — ولا يعمل اليوم.",
  "Jumlah meja, menu, dan modul yang menyala Anda atur di langkah penyiapan setelah ini — semuanya bisa diubah kapan saja.": "عدد الطاولات وقائمة الطعام والوحدات المفعّلة تُضبط كلها في خطوة الإعداد بعد هذه — ويمكن تغييرها جميعًا في أي وقت.",
  "Kalau sertifikat Anda punya halaman di Bhumi ATR/BPN, tautannya sangat membantu admin memeriksa ulang. Harus diawali https://": "إذا كانت لشهادتك صفحة على Bhumi ATR/BPN، فإن رابطها يساعد المشرف كثيرًا في إعادة التحقق. ويجب أن يبدأ بـ https://",
