  "Menekan tombol ini membuat outlet dalam status uji coba. Kisaran biaya di atas berlaku baru setelah uji coba berakhir. Ketentuan lengkap dan pilihan modul yang menyala Anda tentukan dan setujui di langkah berikutnya.": "الضغط على هذا الزر يضع المنفذ في حالة تجريبية. ولا ينطبق نطاق التكلفة أعلاه إلا بعد انتهاء الفترة التجريبية. وأنت من يحدد ويوافق على الشروط الكاملة والوحدات المفعّلة في الخطوة التالية.",
