  "Opsional. Menghitung jejak karbon per menu dari resep dan menampilkannya ke pelanggan sebagai kontribusi yang terlacak.": "اختياري. يحسب البصمة الكربونية لكل صنف في القائمة من الوصفة ويعرضها للعميل بوصفها مساهمة متتبَّعة.",
  "Outlet Anda": "منفذك",
  "Penanda petak": "علامة القطعة",
  "Penukaran belum dibuka. Efek keempat barang di atas belum dijalankan sistem, dan kepemilikannya belum bisa disimpan di dompet — kalau tombol tukar dibuka sekarang, poin Anda berkurang dan Anda tidak mendapat apa pun, bahkan sampai halaman dimuat ulang. Kami memilih mematikannya dan mengatakan alasannya.": "الاستبدال غير مفتوح. فآثار العناصر الأربعة أعلاه لا ينفّذها النظام بعد، ولا يمكن حفظ ملكيتها في المحفظة — ولو فُتح زر الاستبدال الآن لنقصت نقاطك ولم تحصل على شيء، ولا حتى بعد إعادة تحميل الصفحة. اخترنا إيقافه وأن نقول السبب.",
  "Perkiraan luas (ha)": "المساحة التقديرية (ha)",
  "Pilih area yang ingin dirawat": "اختر المنطقة التي تريد العناية بها",
  "Pilih berkas": "اختر ملفًا",
  "Pohon di layar ini dibangkitkan sistem dari luas area yang Anda gambar — bukan pohon yang benar-benar tumbuh di sana, dan bukan pohon yang ditanam siapa pun. Menyiramnya tidak menyerap karbon di dunia nyata. Yang dihitung sungguhan hanya luas area dan estimasi serapannya.": "الأشجار في هذه الشاشة يولّدها النظام من المساحة التي رسمتها — وليست أشجارًا تنمو هناك فعلًا، ولا أشجارًا زرعها أحد. وسقيها لا يمتص أي كربون في العالم الحقيقي. والشيء الوحيد المحسوب فعلًا هو المساحة وتقدير امتصاصها.",
  "Poin Anda sudah cukup, tetapi penukarannya belum dibuka.": "نقاطك كافية، لكن الاستبدال لم يُفتح بعد.",
  "Potret langsung kartunya di tempat terang. Pastikan nama dan nomornya terbaca.": "صوّر البطاقة مباشرة في مكان جيد الإضاءة. وتأكد من وضوح الاسم والرقم.",
  "Pratinjau — halaman ini memperlihatkan bagaimana petak lahan akan ditawarkan. Belum ada transaksi nyata di dalamnya. ⚠︎": "معاينة — تعرض هذه الصفحة كيف ستُطرح قطعة الأرض. ولا توجد أي معاملة حقيقية داخلها. ⚠︎",
