  "Selang panjang": "خرطوم طويل",
  "Semua lahan atas nama akun ini ditampilkan apa adanya — yang sudah aktif maupun yang pengajuannya masih ditinjau. Tekan baris lahan yang aktif untuk membuka halaman pemantauannya.": "تُعرض كل أرض باسم هذا الحساب كما هي — الفعّالة منها والتي ما زال طلبها قيد المراجعة. اضغط صف أرض فعّالة لفتح صفحة متابعتها.",
  "Sertifikat lahan": "شهادة الأرض",
  "Setiap pendaftaran lahan ditinjau lebih dulu oleh tim Glyiv; lahan baru aktif setelah peninjauan itu selesai. Koordinat batas dan pembagian petak juga dihitung saat peninjauan, bukan dari angka yang Anda ketik — karena itu luas yang tampil bisa berbeda dari luas yang Anda ajukan. Serapan karbon yang muncul di halaman lahan adalah": "يراجع فريق Glyiv كل تسجيل أرض أولًا؛ ولا تصبح الأرض فعّالة إلا بعد انتهاء تلك المراجعة. كما تُحسب إحداثيات الحدود وتقسيم القطع أثناء المراجعة، لا من الأرقام التي كتبتها — ولذلك قد تختلف المساحة المعروضة عن المساحة التي تقدمت بها. أما امتصاص الكربون الظاهر في صفحة الأرض فهو",
