  "Tingkat": "المستوى",
  "Tinjauan ini dikerjakan manusia di tim Glyiv. Ini bukan verifikasi resmi pemerintah dan bukan sertifikasi pihak ketiga.": "تُجرى هذه المراجعة على يد أشخاص في فريق Glyiv. وليست تحققًا حكوميًا رسميًا ولا اعتمادًا من طرف ثالث.",
