  "Versi baru sudah selesai dibangun dan sidiknya sudah dipasang di kartu masing-masing, tetapi berkas di tautan unduhan belum diganti. Kalau Anda mencocokkan sekarang, hasilnya akan berbeda — itu bukan tanda berkasnya disusupi.": "انتهى بناء الإصدار الجديد ووُضعت بصماته على كل بطاقة، لكن الملف خلف رابط التنزيل لم يُستبدل بعد. وإن طابقته الآن فستختلف النتيجة — وهذا ليس دليلًا على العبث بالملف.",
