  "Booking meja dari luar outlet muncul di sini secara langsung. Nyalakan “Terima pesanan meja dari luar outlet” di tab Website supaya pelanggan bisa memesannya.": "تظهر هنا مباشرةً حجوزات الطاولات القادمة من خارج المنفذ. فعّل «قبول حجز الطاولات من خارج المنفذ» في تبويب Website حتى يتمكن العملاء من الحجز.",
