  "Berkas rusak saat dikirim. Pilih gambar logonya lagi lalu ulangi unggahan.": "تلف الملف أثناء الإرسال. اختر صورة الشعار مرة أخرى ثم أعد الرفع.",
  "Layanan penyimpanan Glyiv tidak merespons. Ini masalah di sisi kami — coba lagi beberapa menit, dan beri tahu admin kalau tetap gagal.": "خدمة التخزين في Glyiv لا تستجيب. هذه مشكلة لدينا — أعد المحاولة بعد بضع دقائق، وأبلغ المسؤول إن استمر الفشل.",
  "Unggahan gagal karena sebab yang tidak diketahui. Coba lagi.": "فشل الرفع لسبب غير معروف. حاول مجددًا.",
