  "Coba lagi": "حاول مجددًا",
  "Bot ini menyambut, memperkenalkan outlet, dan membawa merek Anda. Ia BELUM menjawab pertanyaan pelanggan atau merekomendasikan menu. Kemampuan itu ada di presentasi produk Glyiv sebagai peta jalan, bukan sebagai yang berjalan hari ini — menjanjikannya di halaman pelanggan berarti menjanjikan sesuatu yang belum ada.": "يرحّب هذا البوت ويعرّف بالمنفذ ويحمل علامتك التجارية. وهو لا يجيب بعد عن أسئلة العملاء ولا يقترح أصنافًا. تلك القدرة مذكورة في عرض منتج Glyiv كخارطة طريق، لا كشيء يعمل اليوم — والوعد بها في صفحة العميل وعدٌ بشيء غير موجود.",
  "Lihat presentasi produknya": "شاهد عرض المنتج",
  "Potret barangnya, atau ketik nama bahannya, untuk melihat estimasinya.": "صوّر العنصر، أو اكتب اسم المادة، لعرض التقدير.",
  "Potret barangnya — foto dikirim ke model penglihatan, karbonnya dihitung di perangkat dari pustaka faktor Glyiv.": "صوّر العنصر — تُرسل الصورة إلى نموذج رؤية، ويُحسب الكربون على جهازك من مكتبة معاملات الانبعاث لدى Glyiv.",
  "Kamera aktif — arahkan ke barangnya, lalu tekan Potret & kenali.": "الكاميرا تعمل — وجّهها نحو العنصر ثم اضغط التقاط والتعرّف.",
  "⏹ Matikan kamera": "⏹ إيقاف الكاميرا",
  "Fotonya terlalu besar untuk dikirim.": "الصورة أكبر من أن تُرسل.",
  "Halaman sudah mencoba mengecilkannya berkali-kali. Potret dari jarak lebih dekat, atau pakai jalur ketik nama bahan di bawah.": "حاولت الصفحة تصغيرها عدة مرات. صوّر من مسافة أقرب، أو استخدم مسار كتابة اسم المادة أدناه.",
  "Pengenalan foto sedang mati: tidak ada model penglihatan aktif di akun Groq Glyiv.": "التعرّف على الصور متوقف: لا يوجد نموذج رؤية نشط في حساب Groq الخاص بـ Glyiv.",
  "Ini di sisi kami, bukan di perangkat Anda. Jalur “ketik nama bahan” di bawah tetap jalan dan memakai pustaka faktor yang sama.": "هذا من جانبنا، لا من جهازك. مسار «اكتب اسم المادة» أدناه ما زال يعمل ويستخدم مكتبة المعاملات نفسها.",
  "Alamat halaman ini belum diizinkan oleh proxy Glyiv.": "عنوان هذه الصفحة غير مسموح به بعد في وسيط Glyiv.",
  "Buka lewat glyiv.github.io atau glyiv.web.app. Kalau ini server uji, tambahkan origin-nya ke ALLOW_ORIGINS di chat-proxy-worker.js lalu deploy ulang worker-nya.": "افتحها عبر glyiv.github.io أو glyiv.web.app. إن كان هذا خادم اختبار، فأضف أصله إلى ALLOW_ORIGINS في chat-proxy-worker.js ثم أعد نشر الـ worker.",
