  "Kunci Groq di worker ditolak.": "رُفض مفتاح Groq في الـ worker.",
  "Perbarui secret GROQ_KEY di Cloudflare (Workers & Pages → glyiv-chat → Settings → Variables and Secrets), lalu deploy ulang.": "حدّث السر GROQ_KEY في Cloudflare (Workers & Pages ← glyiv-chat ← Settings ← Variables and Secrets)، ثم أعد النشر.",
  "Model menolak permintaannya (400).": "رفض النموذج الطلب (400).",
  "Biasanya soal format gambar. Potret ulang; kalau terus berulang, laporkan ke tim Glyiv.": "عادةً مشكلة في صيغة الصورة. أعد التصوير؛ وإن تكرّر الأمر، أبلغ فريق Glyiv.",
