  "Yang mana yang benar?": "أيّها الصحيح؟",
  "Bukan semuanya": "لا شيء منها",
  "tandai belum bisa diperkirakan": "ضع علامة: لا يمكن تقديره بعد",
  "Dihitung dari nama bahan": "محسوب من اسم المادة",
  "Faktor dikonfirmasi pengguna": "أكّد المستخدم المعامل",
  "Nama bahannya belum diisi.": "اسم المادة غير مُدخل.",
  "Tulis bahan utamanya, mis. “daging ayam”, “susu uht”, “gula pasir”.": "اكتب المادة الأساسية، مثل «daging ayam»، «susu uht»، «gula pasir».",
  "Jumlahnya belum diisi.": "الكمية غير مُدخلة.",
  "Isi angka yang lebih besar dari nol, mis. 250.": "أدخل رقمًا أكبر من صفر، مثل 250.",
  "Pustaka Glyiv saat ini berisi bahan pangan, energi, dan kemasan outlet — bukan barang seperti elektronik, pakaian, atau botol kemasan. Kami tidak memaksakan angka untuk sesuatu yang tidak punya faktor bernama. Coba tulis bahan utamanya (mis. “daging ayam”, “susu uht”).": "تغطي مكتبة Glyiv حاليًا المواد الغذائية والطاقة وتغليف المنفذ — لا سلعًا مثل الإلكترونيات أو الملابس أو المشروبات المعبأة. لا نفرض رقمًا على شيء بلا معامل مُسمّى. جرّب كتابة المادة الأساسية (مثل «daging ayam»، «susu uht»).",
  "Anda menandai bahwa tidak satu pun kandidat benar, jadi tidak ada angka yang ditampilkan. Itu jawaban yang jujur. Tulis nama bahan yang lebih spesifik di kolom bawah bila ada.": "أشرتَ إلى أن أيًّا من المرشّحين ليس صحيحًا، لذا لا يُعرض أي رقم. هذه هي الإجابة الصادقة. اكتب اسم مادة أكثر تحديدًا في الحقل أدناه إن وُجد.",
  "Kamera belum aktif.": "الكاميرا ليست مفعّلة بعد.",
  "Tekan “Aktifkan kamera” dulu, atau ketik nama bahannya di bawah.": "اضغط «تشغيل الكاميرا» أولًا، أو اكتب اسم المادة أدناه.",
  "Kamera hanya bisa dipakai lewat HTTPS.": "لا تعمل الكاميرا إلا عبر HTTPS.",
  "Halaman ini sedang dibuka lewat koneksi tidak aman. Buka versi https-nya, lalu coba lagi.": "يتم فتح هذه الصفحة عبر اتصال غير آمن. افتح نسخة https ثم أعد المحاولة.",
  "Izin kamera ditolak.": "رُفض إذن الكاميرا.",
  "Buka ikon gembok di bilah alamat → Izin situs → Kamera → Izinkan, lalu tekan Aktifkan kamera lagi.": "افتح أيقونة القفل في شريط العنوان ← أذونات الموقع ← الكاميرا ← السماح، ثم اضغط تشغيل الكاميرا مرة أخرى.",
  "Tidak ada kamera yang terdeteksi di perangkat ini.": "لم يتم اكتشاف كاميرا على هذا الجهاز.",
  "Pakai perangkat berkamera, atau ketik nama bahannya di bawah.": "استخدم جهازًا مزوّدًا بكاميرا، أو اكتب اسم المادة أدناه.",
  "Kamera sedang dipakai aplikasi lain.": "الكاميرا مستخدَمة من تطبيق آخر.",
  "Tutup aplikasi kamera/konferensi video yang sedang berjalan, lalu coba lagi.": "أغلق تطبيق الكاميرا أو مؤتمرات الفيديو العامل، ثم أعد المحاولة.",
  "Peramban ini tidak mendukung kamera.": "هذا المتصفح لا يدعم الكاميرا.",
  "Pakai Chrome/Safari terbaru, atau ketik nama bahannya di bawah — hasilnya dari pustaka faktor yang sama.": "استخدم إصدارًا حديثًا من Chrome أو Safari، أو اكتب اسم المادة أدناه — والنتيجة من مكتبة المعاملات نفسها.",
  "Kamera dimatikan.": "تم إيقاف الكاميرا.",
  "⚠︎ Belum bisa diperkirakan — model tidak bisa menyebut barang ini apa": "⚠︎ لا يمكن تقديره بعد — لا يستطيع النموذج تحديد ما هذا العنصر",
  "Model menjawab “unknown” — ia melihat sesuatu tetapi tidak mengenalinya, jadi tidak ada nama yang bisa dicari di pustaka faktor. Potret satu barang saja, lebih dekat dan dengan cahaya lebih baik, atau ketik nama bahannya di bawah.": "أجاب النموذج «unknown» — إنه يرى شيئًا لكنه لا يتعرّف عليه، فلا يوجد اسم للبحث عنه في مكتبة المعاملات. صوّر عنصرًا واحدًا فقط، من مسافة أقرب وبإضاءة أفضل، أو اكتب اسم المادة أدناه.",
  "⚠︎ Belum bisa diperkirakan — model tidak cukup yakin barang ini apa": "⚠︎ لا يمكن تقديره بعد — النموذج غير واثق بما يكفي بشأن ماهية هذا العنصر",
  "⚠︎ Belum bisa diperkirakan — model tidak memberi perkiraan massa": "⚠︎ لا يمكن تقديره بعد — لم يقدّم النموذج تقديرًا للكتلة",
  "Aktifkan kamera untuk scan langsung — atau ketik nama bahannya di bawah.": "شغّل الكاميرا للمسح المباشر — أو اكتب اسم المادة أدناه.",
  "Hitung dari pustaka faktor": "احسب من مكتبة المعاملات",
