  "Green di sini berarti terlacak: belanja harian, perjalanan, dan bahan baku dibaca jadi estimasi karbon dari aktivitas nyata — lalu jadi reward untuk pilihan yang berkesinambungan.": "الأخضر هنا يعني متتبَّعًا: تُقرأ مشترياتك اليومية ورحلاتك وموادك الخام لتصير تقديرًا كربونيًا من نشاط حقيقي — ثم مكافأة للخيارات المستدامة.",
  "Untuk individu": "للأفراد",
  "Catat belanja dan kebiasaan harian, lihat jejaknya, kumpulkan reward-nya.": "سجّل مشترياتك وعاداتك اليومية، وشاهد أثرك، واجمع مكافأتك.",
  "Untuk perusahaan": "للشركات",
  "Jejak terlacak dari aktivitas nyata di titik bayar, dapur produksi, dan rantai pasok.": "أثر متتبَّع من نشاط حقيقي عند نقطة الدفع ومطبخ الإنتاج وسلسلة التوريد.",
