  "titik-titik batasnya di peta": "ونقاط حدودها على الخريطة",
  "(sampai 500 pasang koordinat), luas terhitung, jenis lahan, indeks kehijauan, estimasi serapan tahunan berentang ⚠︎, perkiraan jumlah batang, dan sebuah benih acak yang menentukan posisi pohon virtual.": "(حتى 500 زوج إحداثيات)، والمساحة المحسوبة، ونوع الأرض، ومؤشر الاخضرار، وتقدير مُدرَّج بنطاق لامتصاص سنوي ⚠︎، وعدد تقريبي للجذوع، وبذرة عشوائية تحدّد مواضع الأشجار الافتراضية.",
  "5.2 Kenapa poligon diperlakukan sebagai data sensitif.": "5.2 لماذا تُعامل المضلعات كبيانات حساسة.",
