  "peta tempat ia tinggal dan bekerja": "خريطة للمكان الذي يعيش ويعمل فيه",
  ". Karena itu area, jejak perawatan, dan dompet poin Anda": ". ولهذا فإن مساحاتك وسجل رعايتك ومحفظة نقاطك",
  "tidak dapat dibaca admin Glyiv": "لا يمكن لمشرفي Glyiv قراءتها",
  "5.3 Jejak perawatan & dompet poin.": "5.3 سجل الرعاية ومحفظة النقاط.",
  "Untuk tiap pohon virtual yang Anda sentuh: kapan terakhir disiram, berapa kali, dan angka kesehatannya. Dompet menyimpan poin, jumlah penyiraman, dan tingkat.": "لكل شجرة افتراضية تلمسها: متى سُقيت آخر مرة، وكم مرة، ودرجة صحتها. وتخزّن المحفظة النقاط وعدد مرات السقي والمستوى.",
  "Poin bukan uang": "النقاط ليست مالًا",
  "5.4 Ringkasan untuk konsol.": "5.4 ملخص للوحة التحكم.",
  "Supaya tim kami bisa mengurus tingkat pengguna tanpa membuka petanya, kami menyimpan": "كي يتمكن فريقنا من إدارة مستويات المستخدمين دون فتح خرائطهم، نخزّن",
  "angka ringkasnya saja": "الأرقام الموجزة فقط",
  "di tempat terpisah: berapa area, total luas, poin, jumlah penyiraman, dan tingkat. Tidak ada koordinat, nama area, benih, indeks kehijauan, maupun spesies di sana.": "في مكان منفصل: عدد المساحات، وإجمالي المساحة، والنقاط، وعدد مرات السقي، والمستوى. ولا توجد هناك إحداثيات ولا أسماء مساحات ولا بذور ولا مؤشرات اخضرار ولا أنواع.",
  "5.5 Pendaftaran sukarelawan.": "5.5 تسجيل المتطوعين.",
  "Bila Anda mendaftar sebagai sukarelawan survei, yang tersimpan adalah nama, satu kontak, nama daerah, pengalaman, dan status penilaiannya.": "إذا سجّلت كمتطوع مسح ميداني، فإن ما يُخزَّن هو الاسم، وجهة اتصال واحدة، واسم المنطقة، والخبرة، وحالة التقييم.",
  "Tidak ada berkas dan tidak ada KTP": "لا توجد ملفات ولا بطاقة هوية (KTP)",
  "dalam alur ini.": "في هذا المسار.",
  "5.6 Sertifikat lahan yang Anda unggah sendiri.": "5.6 شهادات الأرض التي ترفعها بنفسك.",
  "Anda boleh melampirkan berkas sertifikat lahan (SHM/SHGB, foto atau PDF) saat menggambar sebuah area, dan menempelkan tabel koordinat batasnya. Empat hal yang wajib Anda ketahui.": "يمكنك إرفاق ملف شهادة أرض (SHM/SHGB، صورة أو PDF) عند رسم مساحة، ولصق جدول إحداثيات حدودها. وهناك أربعة أمور يجب أن تعرفها.",
  "(a)": "(أ)",
  "Berkasnya disimpan di brankas yang sama dengan berkas KYC, dengan aturan yang sama:": "يُخزَّن الملف في الخزنة نفسها التي تضم ملفات «اعرف عميلك» (KYC)، وبالقواعد نفسها:",
  "tidak bisa ditimpa atau dihapus setelah terunggah": "لا يمكن استبداله أو حذفه بعد رفعه",
