  "Tinggi dan berat badan adalah data kesehatan.": "الطول ووزن الجسم بيانات صحية.",
  "Undang-Undang Nomor 27 Tahun 2022 menggolongkannya sebagai Data Pribadi yang bersifat spesifik. Kami memperlakukannya sesuai itu: hanya Anda yang bisa membacanya, dan Anda boleh menolak mengisinya tanpa kehilangan fitur lain.": "يصنّف القانون رقم 27 لسنة 2022 هذه البيانات كبيانات شخصية ذات طبيعة خاصة. ونحن نعاملها وفق ذلك: أنت وحدك من يستطيع قراءتها، ويمكنك رفض إدخالها دون أن تفقد أي ميزة أخرى.",
  "Tiap catatan harian menyimpan: jenisnya (barang atau IMT), tanggal, estimasi CO₂e beserta batas bawah dan atasnya ⚠︎, tingkat mutu data, label singkat, dan sebuah blok rincian. Untuk catatan IMT, blok rincian itu memuat": "يخزّن كل سجل يومي: نوعه (سلعة أو مؤشر كتلة الجسم)، والتاريخ، وتقدير CO₂e مع حدّيه الأدنى والأعلى ⚠︎، ومستوى جودة البيانات، وتسمية قصيرة، وكتلة تفاصيل. وبالنسبة لسجلات مؤشر كتلة الجسم، تحتوي كتلة التفاصيل تلك على",
