  ", bukan dari foto. Estimasi emisinya dihitung di perangkat Anda dari pustaka faktor emisi kami; yang tersimpan hanyalah catatan pada butir 6.1.": "، لا من صورة. ويُحسب تقدير انبعاثاتها على جهازك من مكتبة معاملات الانبعاث لدينا؛ ولا يُخزَّن سوى السجل المذكور في البند 6.1.",
  "Catatan harian Anda": "سجلاتك اليومية",
  ". Tidak ada alur kerja Glyiv yang menuntut karyawan membaca apa yang seseorang beli atau berapa berat badannya. Anda bisa menghapus tiap catatan kapan saja.": ". ولا يوجد أي سير عمل في Glyiv يتطلب من موظف قراءة ما اشتراه شخص ما أو كم يزن. ويمكنك حذف أي سجل متى شئت.",
