  "Saat Anda mengirim pesan kepada Gly, yang dikirim keluar adalah: teks yang Anda ketik, sampai sepuluh giliran terakhir percakapan di tab itu, dan": "عندما ترسل رسالة إلى Gly، فإن ما يُرسل هو: النص الذي تكتبه، وحتى آخر عشر مداخلات من المحادثة في ذلك اللسان، و",
  "konteks halaman": "سياق الصفحة",
  "berupa judul halaman, judul besarnya, ringkasan meta, dan alamat halamannya. Tidak ada pengenal akun, alamat surel, atau isi dokumen Anda yang ikut.": "المؤلف من عنوان الصفحة وعنوانها الرئيسي ووصف الميتا وعنوانها الإلكتروني. ولا يُرسل معه أي معرّف حساب ولا عنوان بريد إلكتروني ولا محتوى مستنداتك.",
  "Percakapan itu melewati proksi kami di Cloudflare lalu diteruskan ke penyedia model bahasa": "تمر تلك المحادثة عبر الوسيط (proxy) لدينا في Cloudflare ثم تُحال إلى مزوّد نموذج اللغة",
  "Glyiv tidak menyimpan percakapan Gly di basis datanya": "Glyiv لا يخزّن محادثات Gly في قاعدة بياناته",
  "; riwayat percakapan hidup di memori tab Anda dan hilang saat tab ditutup. Yang tidak bisa kami janjikan adalah pencatatan di sisi Cloudflare dan Groq — itu tunduk pada kebijakan mereka, dan karena itu": "؛ فسجل المحادثة يعيش في ذاكرة لسان التصفح لديك ويختفي عند إغلاقه. أما ما لا نستطيع الوعد به فهو التسجيل لدى Cloudflare وGroq — فذلك يخضع لسياساتهما، ولهذا السبب",
  "jangan mengetik data pribadi atau rahasia usaha ke dalam kotak obrolan": "لا تكتب بيانات شخصية أو أسرارًا تجارية في صندوق المحادثة",
  "Sebagian besar pemrosesan kami berdiri di atas": "تقوم معظم عمليات المعالجة لدينا على",
  "persetujuan Anda": "موافقتك",
  "pemenuhan perjanjian": "تنفيذ العقد",
  "— artinya: tanpa data itu layanannya memang tidak bisa berjalan. Data kesehatan (IMT) hanya diproses bila Anda memasukkannya sendiri, dan Anda bisa berhenti kapan saja.": "— أي أنه بدون تلك البيانات لا تستطيع الخدمة العمل أصلًا. أما البيانات الصحية (مؤشر كتلة الجسم) فلا تُعالَج إلا إذا أدخلتها بنفسك، ويمكنك التوقف متى شئت.",
  "Dasar pemrosesan kami mengikuti Pasal 20 Undang-Undang Nomor 27 Tahun 2022, dengan pembagian sebagai berikut.": "تتبع أسس المعالجة لدينا المادة 20 من القانون رقم 27 لسنة 2022، وفق التقسيم التالي.",
  "Akun & sesi": "الحساب والجلسة",
  "Pemenuhan kewajiban perjanjian — tanpa akun, layanan berakun tidak bisa diberikan.": "تنفيذ الالتزامات التعاقدية — فبدون حساب لا يمكن تقديم الخدمات القائمة على الحسابات.",
  "Pesanan & operasional outlet": "الطلبات وعمليات المنفذ (outlet)",
  "Pemenuhan kewajiban perjanjian dengan outlet, dan kepentingan yang sah untuk menghitung meteran penagihan.": "تنفيذ الالتزامات التعاقدية مع المنفذ (outlet)، والمصلحة المشروعة في احتساب عدّاد الفوترة.",
  "Dokumen identitas usaha (KTP/NIB)": "مستندات هوية النشاط التجاري (KTP/NIB)",
  "Persetujuan Anda saat mengunggahnya, dan kepentingan yang sah untuk memastikan outlet yang kami layani benar-benar ada.": "موافقتك عند رفعها، والمصلحة المشروعة في التأكد من أن المنفذ (outlet) الذي نخدمه موجود فعلًا.",
  "Pengukuran pohon, area lahan, catatan harian": "قياسات الأشجار، ومساحات الأرض، والسجلات اليومية",
  "Persetujuan Anda. Semua ini Anda masukkan sendiri, dan bisa Anda hapus sendiri.": "موافقتك. فأنت من يُدخل كل ذلك بنفسه، وتستطيع حذفه بنفسك.",
  "Tinggi & berat badan (IMT)": "الطول ووزن الجسم (مؤشر كتلة الجسم)",
  "Persetujuan Anda yang diberikan secara khusus saat mengisinya. Data ini": "موافقتك الممنوحة تحديدًا عند إدخالها. وهذه البيانات",
  "diproses untuk tujuan lain.": "تُعالَج لأي غرض آخر.",
  "Notifikasi ponsel": "إشعارات الهاتف",
  "Persetujuan Anda saat menyalakannya.": "موافقتك عند تفعيلها.",
  "Menarik persetujuan itu mudah dan tidak dihukum: hapus catatannya, matikan notifikasinya, atau minta kami menghapus akun Anda. Menarik persetujuan tidak membatalkan keabsahan pemrosesan yang sudah terjadi sebelumnya.": "سحب الموافقة سهل ولا يترتب عليه عقاب: احذف السجل، أو أوقف الإشعار، أو اطلب منا حذف حسابك. وسحب الموافقة لا يُبطل مشروعية المعالجة التي جرت قبل ذلك.",
  "memakai data Anda untuk pemasangan iklan tertarget, tidak memperjualbelikan data Anda, dan tidak mengambil keputusan yang menimbulkan akibat hukum semata-mata dari pemrosesan otomatis.": "لا نستخدم بياناتك لعرض إعلانات موجَّهة، ولا نبيع بياناتك أو نشتريها، ولا نتخذ قرارات ذات أثر قانوني بالاعتماد الحصري على المعالجة الآلية.",
  "Sebagian data memang harus bisa dibaca tim kami untuk mengurus akun, tagihan, dan tinjauan. Sebagian lagi": "بعض البيانات يجب فعلًا أن يكون فريقنا قادرًا على قراءتها لإدارة الحسابات والفواتير والمراجعات. أما بعضها الآخر فقد",
  "sengaja kami tutup dari diri kami sendiri": "أغلقناه عمدًا في وجه أنفسنا",
  ": pengukuran pohon Anda, area lahan Anda, dan catatan harian Anda tidak bisa dibaca admin Glyiv, dan itu ditegakkan aturan di server — bukan sekadar janji kebijakan internal.": ": فقياسات أشجارك ومساحات أرضك وسجلاتك اليومية لا يستطيع مشرفو Glyiv قراءتها، وهذا مفروض بقواعد على الخادم — لا مجرد وعد في سياسة داخلية.",
