  "“Admin Glyiv” berarti sejumlah kecil alamat surel yang terdaftar di server kami. Hak itu dinilai dari surel pada token identitas yang ditandatangani Google,": "«مشرف Glyiv» تعني عددًا صغيرًا من عناوين البريد الإلكتروني المسجّلة على خادمنا. ويُقيَّم هذا الحق من البريد الوارد في رمز الهوية الموقَّع من Google،",
  "dari medan di dalam dokumen yang bisa ditulis pengguna — sehingga tidak ada yang bisa mengangkat dirinya sendiri menjadi admin.": "من حقل داخل مستند يستطيع المستخدم الكتابة فيه — فلا يستطيع أحد ترقية نفسه إلى مشرف.",
