  ". Permintaan baca dari akun admin ke sana ditolak sama seperti permintaan dari orang asing.": ". فطلب القراءة من حساب مشرف إلى هناك يُرفض تمامًا كما يُرفض طلب من شخص غريب.",
  "9.3 Batas yang kami sebut apa adanya.": "9.3 الحد الذي نذكره كما هو.",
  "Aturan server tidak berlaku untuk kredensial administratif tingkat proyek pada infrastruktur Google Cloud — kredensial itu memang melewati aturan, dan itu berlaku pada setiap layanan yang dibangun di atas Firebase. Kredensial tersebut kami pakai hanya untuk pengoperasian dan pemulihan, tidak untuk membaca isi dokumen pengguna. Kalau suatu hari kami butuh angka gabungan, kami menghitungnya lalu menyimpan": "قواعد الخادم لا تسري على بيانات الاعتماد الإدارية على مستوى المشروع في بنية Google Cloud — فتلك البيانات تتجاوز القواعد فعلًا، وهذا ينطبق على كل خدمة مبنية على Firebase. ونحن نستخدمها للتشغيل والاستعادة فقط، لا لقراءة محتوى مستندات المستخدمين. وإذا احتجنا يومًا أرقامًا مجمّعة، فإننا نحسبها ثم نخزّن",
  "hasil gabungannya saja": "النتيجة المجمّعة فقط",
  "di tempat terpisah — persis yang sudah kami lakukan pada butir 5.4.": "في مكان منفصل — وهو تحديدًا ما فعلناه في البند 5.4.",
  "Kami tidak pernah menyerahkan data Anda kepada aparat atau pihak ketiga mana pun kecuali ada dasar hukum yang mengharuskannya. Bila itu terjadi dan hukum tidak melarang kami memberitahu, kami akan memberitahu Anda.": "نحن لا نسلّم بياناتك إطلاقًا إلى السلطات أو أي طرف ثالث ما لم يوجد أساس قانوني يوجب ذلك. وإذا حدث ذلك ولم يمنعنا القانون من إبلاغك، فسنبلغك.",
  "Kami memakai infrastruktur Google Cloud. Berkas Anda — foto menu, QRIS, dokumen KTP dan NIB — disimpan di": "نستخدم بنية Google Cloud. وتُخزَّن ملفاتك — صور القائمة، وQRIS، ومستندات KTP وNIB — في",
