  ", jadi data teks yang Anda serahkan memang diproses di luar Indonesia. Kami menuliskannya terus terang karena Anda berhak tahu, dan memindahkannya ke wilayah Indonesia ada dalam peta jalan kami.": "، لذا فإن البيانات النصية التي تقدّمها تُعالَج فعلًا خارج إندونيسيا. ونكتب ذلك بصراحة لأن من حقك أن تعرف، ونقلها إلى منطقة إندونيسية مدرج في خارطة طريقنا.",
