  "10.1 Transfer ke luar negeri.": "10.1 النقل إلى خارج البلاد.",
  "Karena basis data dokumen berada di Amerika Serikat, pemrosesan data pribadi Anda melibatkan transfer ke luar wilayah Indonesia. Transfer itu dilakukan kepada Google LLC selaku penyedia infrastruktur, tunduk pada perjanjian pemrosesan data Google Cloud, dan hanya untuk tujuan yang tertulis di kebijakan ini.": "لأن قاعدة بيانات المستندات موجودة في الولايات المتحدة، فإن معالجة بياناتك الشخصية تتضمن نقلًا خارج الإقليم الإندونيسي. ويتم هذا النقل إلى Google LLC بصفتها مزوّد البنية التحتية، ويخضع لاتفاقية معالجة البيانات الخاصة بـ Google Cloud، ولا يكون إلا للأغراض المكتوبة في هذه السياسة.",
