  "Menuliskan angka bulan yang tidak benar-benar dijalankan mesin mana pun adalah kebohongan yang rapi, jadi kami tidak menuliskannya. Yang berlaku hari ini: data bertahan sampai Anda menghapusnya atau meminta kami menghapusnya.": "كتابة عدد أشهر لا تنفّذه أي آلة فعليًا كذبة أنيقة، ولذلك لا نكتبها. أما ما يسري اليوم فهو: تبقى البيانات إلى أن تحذفها أنت أو تطلب منا حذفها.",
  "Akun & profil": "الحساب والملف الشخصي",
  "Selama akun Anda ada. Dihapus atas permintaan Anda.": "طالما ظل حسابك قائمًا. ويُحذف بناءً على طلبك.",
  "menghapusnya. Anda bisa melakukannya sendiri kapan saja.": "تحذفها. ويمكنك فعل ذلك بنفسك متى شئت.",
