  "Bila kami kelak memasang jadwal penghapusan otomatis, kebijakan ini diperbarui dengan nomor versi baru sebelum jadwal itu berjalan.": "وإذا وضعنا لاحقًا جدولًا للحذف التلقائي، فستُحدَّث هذه السياسة برقم إصدار جديد قبل تشغيل ذلك الجدول.",
  "Kami tidak menulis “mitra tepercaya” — itu tidak memberi tahu apa pun. Di bawah ini nama perusahaannya, apa yang mereka terima, dan kenapa. Dua di antaranya perlu Anda tahu meski terasa sepele:": "نحن لا نكتب «شركاء موثوقون» — فذلك لا يخبرك بشيء. وفيما يلي أسماء الشركات، وما تتلقاه، ولماذا. واثنتان منها ينبغي أن تعرف عنهما رغم أنهما تبدوان بسيطتين:",
