  "Proksi obrolan kami berjalan di jaringan mereka, supaya kunci layanan model tidak pernah berada di peramban Anda.": "يعمل وسيط المحادثة لدينا على شبكتهم، حتى لا يكون مفتاح خدمة النموذج موجودًا في متصفحك أبدًا.",
