  "— bukan “penghasilan” — dan syaratnya akan ditulis terpisah. Tidak ada janji penghasilan dalam dokumen ini, dan tidak boleh ada di mana pun dalam produk kami.": "— لا «دخل» — وستُكتب شروطه بشكل منفصل. ولا يوجد أي وعد بدخل في هذا المستند، ولا يجوز وجوده في أي مكان في منتجاتنا.",
  "Kami dapat mengubah aturan permainan, menyetel ulang poin, atau menghentikan unsur permainan sama sekali. Karena poin tidak bernilai uang, perubahan semacam itu tidak menimbulkan hak ganti rugi.": "يجوز لنا تغيير قواعد اللعبة أو إعادة ضبط النقاط أو إيقاف عنصر اللعب كليًا. ولأن النقاط لا قيمة نقدية لها، فإن تغييرًا كهذا لا ينشئ أي حق في تعويض.",
