  "saat ini hanya berlaku untuk sesi yang sedang berjalan; kepemilikannya belum bisa disimpan. Itu ditulis apa adanya di layarnya, dan bukan cacat yang sedang kami sembunyikan.": "تسري حاليًا على الجلسة الجارية فقط؛ ولا يمكن بعدُ حفظ الملكية. وهذا مكتوب كما هو على شاشته، وليس عيبًا نخفيه.",
