  "⚠︎ Estimasi, bukan sertifikasi. Titik terlemahnya:": "⚠︎ تقدير، لا شهادة. وأضعف نقطة فيه:",
  "berat dari foto": "الوزن المستخرج من الصورة",
  "— model menebak massa tanpa acuan skala, dan seluruh angka berskala lurus dengan tebakan itu. Pustaka faktornya condong Eropa/global sehingga faktor Indonesia bisa berbeda, dan sebagian besar barisnya tier T3–T4 (belum ada T1). Jalur berbasis harga": "— يخمّن النموذج الكتلة دون مرجع للقياس، وتتناسب كل الأرقام طرديًا مع ذلك التخمين. وتميل مكتبة العوامل إلى أوروبا/العالم، لذا قد تختلف عوامل إندونيسيا، ومعظم أسطرها من الفئة T3–T4 (ولا شيء عند T1 بعد). أما المسار القائم على السعر فقد",
  "sengaja dimatikan": "أُوقف عمدًا",
  ": faktor EEIO/EXIOBASE Indonesia belum ditarik dari rilis resmi, jadi angka spend-based tidak dihitung dari ingatan. Mendukung \"kontribusi/jejak terlacak\" untuk imbalan Glyiv, bukan klaim netral karbon.": "‏: لم تُستخرج عوامل EEIO/EXIOBASE الخاصة بإندونيسيا من الإصدارات الرسمية، لذلك لا تُحسب الأرقام القائمة على الإنفاق من الذاكرة. وهو يدعم «مساهمة/بصمة متتبَّعة» لمكافآت Glyiv، لا ادعاء الحياد الكربوني.",
