  "setiap perbaikan yang kami pasang di web langsung ikut terbawa": "كل إصلاح ننشره على الويب ينتقل إليه فورًا",
  "— tidak perlu memasang ulang.": "— دون حاجة إلى إعادة التثبيت.",
  "Satu aplikasi untuk seluruh outlet. Masuk dengan akun Google;": "تطبيق واحد لكل المنافذ. سجّل الدخول بحساب Google؛",
