  "Sebagian kecil data tetap ada sesudah akun dihapus — bukan karena kami ingin menyimpannya, tetapi karena ia juga milik pihak lain atau dituntut hukum. Semuanya disebutkan di bawah, tanpa dihaluskan.": "يبقى جزء صغير من البيانات بعد حذف الحساب — ليس لأننا نريد الاحتفاظ به، بل لأنه يخصّ أطرافًا أخرى أيضًا أو لأن القانون يقتضيه. كل ذلك مذكور أدناه، دون تلطيف.",
