  ". Bila Anda tidak puas dengan jawaban kami, Anda berhak mengadu kepada lembaga yang berwenang di bidang pelindungan data pribadi, dan berhak menempuh jalur hukum.": ". إذا لم تكن راضيًا عن ردّنا، فلك الحق في تقديم شكوى إلى الجهة المختصة بحماية البيانات الشخصية، ولك الحق في اللجوء إلى القضاء.",
