  "Dokumen KYC dan berkas sertifikat lahan, bila ada. ⚠︎ Kecuali berkas KTP/NIB yang masih menjadi dasar persetujuan usaha yang berlaku: berkas itu baru dihapus saat hubungan usaha berakhir (Kebijakan Privasi Pasal 14.3).": "مستندات اعرف عميلك وملفات شهادات الأراضي، إن وُجدت. ⚠︎ باستثناء ملفات بطاقة الهوية/رخصة العمل التي لا تزال تستند إليها اتفاقية عمل سارية: تُحذف تلك عند انتهاء علاقة العمل (سياسة الخصوصية، المادة 14.3).",
