  ". Glyiv mengintegrasikan green receipt + wallet: tiap transaksi punya rincian item dan jejak karbonnya. Dibangun via mitra berlisensi (rezim PJP Bank Indonesia); token $GLYIV hanya utilitas, bukan alat bayar.": ". يدمج Glyiv الإيصال الأخضر مع المحفظة: لكل معاملة تفصيلها الصنفي وبصمتها الكربونية. يُبنى عبر شركاء مرخَّصين (نظام PJP لبنك إندونيسيا)؛ رمز $GLYIV للاستخدام الوظيفي فقط، وليس أداة دفع.",
