  "NDVI + citra Sentinel mendukung monitoring kondisi pohon dan deteksi anomali — alert deforestasi, perubahan vegetasi, sinyal risiko. Catatan: NDVI bukan \"meteran karbon\"; akurasi grade-kredit butuh kalibrasi data lapangan (selaras panduan IPCC).": "يدعم NDVI وصور Sentinel مراقبة حالة الأشجار وكشف الشذوذ — تنبيهات إزالة الغابات، وتغيّر الغطاء النباتي، وإشارات المخاطر. ملاحظة: NDVI ليس «عدّاد كربون»؛ فالدقة بدرجة الأرصدة تتطلّب معايرة ببيانات ميدانية (بما يتوافق مع إرشادات IPCC).",
