  "Pemilik lahan onboarding → kapasitas serapan dihitung lewat NDVI/Google Earth Engine → tiap hektar di-tokenisasi (ERC-721) lalu difraksi (ERC-3643). Institusi & retail membeli Carbon Absorption Token untuk mendanai dan menebus — disiplin MRV, selaras registri (SRN-PPI/SRUK/SPE-GRK).": "ينضم ملّاك الأراضي → تُحسب طاقة الامتصاص عبر NDVI/Google Earth Engine → يُرمَّز كل هكتار (ERC-721) ثم يُجزَّأ (ERC-3643). تشتري المؤسسات وتجارة التجزئة Carbon Absorption Token للتمويل والإحالة إلى التقاعد — بانضباط MRV، وبما يتوافق مع السجلات (SRN-PPI/SRUK/SPE-GRK).",
