  "Roadmap & business model bertahap (Fase 0–4) tersedia lengkap untuk investor, termasuk model pendapatan & struktur biaya tiap fase.": "خارطة الطريق ونموذج العمل المتدرّج (المراحل 0–4) متاحان بالكامل للمستثمرين، بما في ذلك نموذج الإيرادات وهيكل التكاليف لكل مرحلة.",
