  "Sebagian dari tiap pesanan mengalir — secara transparan dan dapat diaudit — ke komunitas hijau mitra. Pelanggan mengumpulkan Green Points dan melihat persis ke mana dampaknya pergi.": "يتدفّق جزء من كل طلب — بشفافية وقابلية للتدقيق — إلى المجتمعات الخضراء الشريكة. يجمع العملاء Green Points ويرون بالضبط إلى أين يذهب أثرهم.",
