  "Seperti Gojek yang dulu mendahului regulasi, Glyiv bertujuan menjadi infrastruktur publik digital yang market-driven — sebuah \"standar hijau\" yang dipercaya pasar, lalu diadopsi kebijakan. Dibangun bertahap, integritas dulu, agar kredibel di mata regulator & dunia.": "كما سبق Gojek التنظيم، يهدف Glyiv إلى أن يكون بنية تحتية رقمية عامة يقودها السوق — «معيارًا أخضر» يثق به السوق ثم تتبنّاه السياسات. يُبنى على مراحل، والنزاهة أولًا، ليكون جديرًا بالثقة لدى الجهات التنظيمية والعالم.",
  "Serapan per hektar": "الامتصاص لكل هكتار",
  "Sertifikat + KYC": "شهادة + KYC",
  "sesuatu yang nyata.": "شيئًا حقيقيًا.",
  "Setelah ribuan outlet menghasilkan data karbon level-item, Glyiv berkembang menjadi lapisan fondasi: data yang dijual ke institusi global, e-wallet pertama yang menampilkan karbon per item, dan marketplace aset karbon nyata (Tree RWA) dengan monitoring satelit.": "بعد أن تولّد آلاف المنافذ بيانات كربون على مستوى الصنف، يتطوّر Glyiv ليصبح طبقة أساس: بيانات تُباع للمؤسسات العالمية، وأول محفظة إلكترونية تعرض الكربون لكل صنف، وسوق أصول كربونية حقيقية (Tree RWA) مع مراقبة بالأقمار الصناعية.",
