  "Struk kertas membuang data level-item — apa yang benar-benar dibeli — dan bank pun cuma melihat kategori. Kontribusi hijau? Tak terlacak.": "الإيصالات الورقية تهدر البيانات على مستوى الصنف — ما اشتُري فعلًا — والبنوك لا ترى سوى فئات عامة. أما المساهمة الخضراء؟ فغير متتبَّعة إطلاقًا.",
