  "Sumber: World Bank (harga karbon 2024), Ecosystem Marketplace (VCM 2024), IDXCarbon. Angka pasar — bukan proyeksi Glyiv.": "المصادر: World Bank (تسعير الكربون 2024)، Ecosystem Marketplace ‏(VCM 2024)، IDXCarbon. أرقام سوقية — وليست توقّعات Glyiv.",
