  "aset karbon": "أصول الكربون",
  "— dalam satu tumpukan.": "— في حزمة واحدة.",
  "Kebanyakan solusi karbon hanya menyentuh satu lapisan. Glyiv menyatukan empat: perdagangan, kecerdasan, keberlanjutan, dan finansial. Data mengalir naik dari transaksi nyata; nilai mengalir turun kembali ke merchant & komunitas.": "معظم حلول الكربون تمسّ طبقة واحدة فقط. أما Glyiv فيجمع أربعًا: التجارة، والذكاء، والاستدامة، والتمويل. تتدفّق البيانات صعودًا من معاملات حقيقية؛ وتتدفّق القيمة نزولًا إلى التجّار والمجتمعات.",
  "tempat data lahir": "حيث تولد البيانات",
