  "Carbon Flow · thesis Glyiv": "Carbon Flow · أطروحة Glyiv",
  "Satu cangkir kopi,": "فنجان قهوة واحد،",
  "berubah jadi dampak yang terlacak.": "يتحوّل إلى أثر متتبَّع.",
  "Inilah inti Glyiv: mesin yang mengubah transaksi biasa menjadi data karbon, lalu menjadi aset, lalu menjadi pohon yang benar-benar tumbuh. Ikuti perjalanannya.": "هذا هو قلب Glyiv: محرّك يحوّل معاملة عادية إلى بيانات كربون، ثم إلى أصل، ثم إلى شجرة تنمو فعلًا. تابع الرحلة.",
