  "pohon & komunitas": "الأشجار والمجتمع",
  "Integritas dulu: perhitungan selaras GHG Protocol (spend-based→item-based), aset karbon mengikuti disiplin MRV & registri. Tokenisasi hanya lapisan utilitas/loyalitas — bukan mengaku sebagai unit karbon teregulasi.": "النزاهة أولًا: الحسابات متوافقة مع GHG Protocol (من الإنفاق إلى الصنف)، وأصول الكربون تتبع انضباط MRV والسجلات. أما الترميز فطبقة وظيفية/ولاء فقط — ولا يدّعي أبدًا أنه وحدة كربون منظَّمة.",
  "Yang Glyiv bangun": "ما يبنيه Glyiv",
  "Enam fokus,": "ستة محاور،",
