  "Data karbon level-item — komoditas yang dicari dunia.": "بيانات كربون على مستوى الصنف — السلعة التي يريدها العالم.",
  "Bank & korporasi butuh data Scope 3 yang granular untuk IFRS S2 & disclosure. Glyiv menghasilkannya langsung dari sumber: tiap item, tiap transaksi — bukan estimasi kategori.": "تحتاج البنوك والشركات إلى بيانات Scope 3 تفصيلية من أجل IFRS S2 والإفصاح. ويولّدها Glyiv مباشرةً من المصدر: كل صنف، وكل معاملة — لا تقديرات فئوية.",
