  "Pemilik lahan mendaftarkan lahan yang ditanami → kapasitas serapan dihitung lewat NDVI/Google Earth Engine → di-tokenisasi lewat rel": "يسجّل ملّاك الأرض أراضيهم المزروعة → تُحسب طاقة الامتصاص عبر NDVI/Google Earth Engine → ثم تُرمَّز على قضبان",
