  "04 · Dashboard ESG & Monitoring": "04 · لوحة ESG والمراقبة",
  "Carbon ledger otomatis jadi dashboard ESG siap-audit untuk bisnis. NDVI + citra Sentinel memantau kondisi pohon & mendeteksi anomali (alert deforestasi). Catatan jujur: NDVI bukan “meteran karbon” — akurasi grade-kredit butuh kalibrasi lapangan (selaras IPCC).": "يتحوّل سجل الكربون تلقائيًا إلى لوحة ESG جاهزة للتدقيق للأعمال. ويراقب NDVI وصور Sentinel حالة الأشجار ويرصدان الشذوذ (تنبيهات إزالة الغابات). ملاحظة صادقة: NDVI ليس «عدّاد كربون» — فالدقة بدرجة الأرصدة تتطلّب معايرة ميدانية (بما يتوافق مع IPCC).",
  "Peluang Pasar": "فرصة السوق",
