  "Estimasi industri (green economy & carbon market outlook). Ditampilkan sebagai skala peluang, bukan proyeksi Glyiv.": "تقديرات قطاعية (آفاق الاقتصاد الأخضر وسوق الكربون). تُعرض كمقياس للفرصة، لا كتوقّعات لـ Glyiv.",
  "Kenapa Glyiv menang": "لماذا ينتصر Glyiv",
