  "dimulai dari satu cangkir kopi.": "يبدأ من فنجان قهوة واحد.",
  "Infrastruktur karbon tak dibangun dari atas. Ia tumbuh dari transaksi nyata. Jadi kami mulai dari yang paling sederhana & paling sering terjadi: memesan kopi. Dari sanalah data pertama lahir, komunitas terbentuk, dan mesin karbon mulai berputar.": "بنية الكربون لا تُبنى من الأعلى. بل تنمو من معاملات حقيقية. لذلك نبدأ من أبسط الأفعال وأكثرها تكرارًا: طلب فنجان قهوة. من هناك تولد البيانات الأولى، وتتشكّل المجتمعات، ويبدأ محرّك الكربون بالدوران.",
