  "Jejak karbon produk spesifik yang sudah diverifikasi pihak ketiga (ISO 14067 / EPD) — kelas data masukan tertinggi, bukan status angka Glyiv.": "بصمة كربونية خاصة بمنتج بعينه سبق أن تحقّق منها طرف ثالث (ISO 14067 / EPD) — أعلى فئة لبيانات المدخلات، لا حالة أرقام Glyiv نفسها.",
  "Baca tier ini sebagai kualitas data masukan, bukan klaim Glyiv.": "اقرأ هذه المستويات على أنها جودة بيانات المدخلات، لا ادعاءً من Glyiv.",
  "Tier A menggambarkan kelas data terbaik yang ada di industri (PCF pihak ketiga, ISO 14067 / EPD) — bukan status angka yang kami keluarkan hari ini. Output Glyiv saat ini adalah": "يصف المستوى A أفضل فئة بيانات موجودة في القطاع (PCF من طرف ثالث، ISO 14067 / EPD) — لا حالة الأرقام التي ننشرها اليوم. فما يُخرجه Glyiv حاليًا هو",
