  "(POS outlet), kami melihat tiap item — bukan sekadar “Rp50.000 di sebuah outlet”. Inilah aset yang dicari institusi besar dan, kelak, pasar karbon internasional.": "(نقطة بيع المنفذ)، نرى كل صنف — لا مجرد «Rp50.000 في منفذ ما». هذا هو الأصل الذي تبحث عنه المؤسسات الكبرى، ولاحقًا أسواق الكربون الدولية.",
