  "— data publik ekosistem QRIS Indonesia, bukan traksi Glyiv. Angka survei berasal dari riset internal berskala kecil dan bersifat indikatif, belum studi yang representatif secara statistik. Glyiv belum beroperasi komersial di outlet mana pun: yang ada baru validasi awal, bukan bukti lapangan.": "— بيانات عامة عن منظومة QRIS الإندونيسية، لا جذبًا لـ Glyiv. وأرقام الاستبيان مصدرها بحث داخلي صغير النطاق وهي إرشادية فقط، وليست دراسة ممثِّلة إحصائيًا. ولا يعمل Glyiv تجاريًا في أي منفذ حتى الآن: ما هو موجود تحقّق مبكر، لا إثبات ميداني.",
