  "di atas: citranya terbaca berbeda dari jenis lahan yang Anda pilih. Kami tidak menolak pilihan Anda — kami hanya mencatat bahwa Anda sudah membacanya.": "أعلاه: الصور تُقرأ بشكل مختلف عن نوع الأرض الذي اخترته. نحن لا نرفض اختيارك — نحن فقط نسجّل أنك قرأت هذا.",
