  ", angka tanpa tanda dihitung sistem dari poligon batas lahan — karena itu bisa berbeda dari luas yang Anda ajukan. Angka bertanda": "، الأرقام غير المعلَّمة يحسبها النظام من مضلّع حدود الأرض — لذلك قد تختلف عن المساحة التي قدّمتها. الأرقام المعلَّمة بـ",
  "belum melewati perhitungan itu: pada baris pengajuan ia angka yang Anda ketik, pada lahan yang poligon batasnya belum tercatat ia luas yang Anda klaim.": "لم تمرّ بهذا الحساب: في صف الطلب هو الرقم الذي كتبته، وفي الأرض التي لم يُسجَّل مضلّع حدودها بعد هو المساحة التي ذكرتها.",
  "Rincian dari baris pengajuan di tabel atas — isi yang Anda kirim beserta keterangan statusnya. Tekan salah satu untuk membukanya.": "تفاصيل صف الطلب في الجدول أعلاه — ما أرسلته مع بيان حالته. اضغط على أحدها لفتحه.",
  "Angka yang Anda ketik. Luas resmi dihitung ulang dari poligon batas saat peninjauan.": "الرقم الذي كتبته. يُعاد حساب المساحة الرسمية من مضلّع الحدود عند المراجعة.",
