  "← Semua aset": "← كل الأصول",
  "Admin meminta perbaikan pada berkas lahan ini. Lahannya tetap tercatat atas nama Anda dan tetap bisa dipantau — hubungi admin Glyiv untuk tahu bagian mana yang perlu diperbaiki.": "طلب المشرف تصحيحات على ملف هذه الأرض. لا تزال الأرض مسجّلة باسمك ويمكن متابعتها — تواصل مع مشرف Glyiv لمعرفة الجزء الذي يحتاج إلى تصحيح.",
