  ", bukan terukur atau terverifikasi. Faktor emisi masih indikatif. Sertifikasi, MRV, dan registri masih peta jalan — belum menjadi kemampuan yang berjalan.": "، وليس مقيسًا أو موثّقًا. معاملات الانبعاث لا تزال إرشادية. الاعتماد وMRV والسجل لا تزال ضمن خارطة الطريق — وليست قدرة عاملة بعد.",
  "yang sudah berjalan sebagai sistem nyata; vertikal lain masih peta jalan dan ditandai apa adanya. Tidak ada angka contoh di halaman ini.": "يعمل كنظام حقيقي؛ أما القطاعات الأخرى فلا تزال ضمن خارطة الطريق وتُذكر كما هي. لا توجد أرقام أمثلة في هذه الصفحة.",
