  "Sistem GIP Outlet multi-tenant yang sudah berjalan di pilot. Berikut yang sudah aktif hari ini.": "نظام GIP Outlet متعدّد المستأجرين يعمل بالفعل في التجربة الرائدة. وفيما يلي ما هو نشِط اليوم.",
