  "Tanpa sistem level": "بلا نظام مستويات",
  "⚠︎ Peramban pengguna ini melaporkan bahwa daftar areanya sendiri sudah": "⚠︎ يُبلغ متصفّح هذا المستخدم بأن قائمة مناطقه نفسها قد",
  "Tombol pengaturan menyala setelah status level pengguna ini selesai dibaca dari server.": "يُفعَّل زر الإعدادات بعد اكتمال قراءة حالة مستوى هذا المستخدم من الخادم.",
