  "Bedengan sayur berbaris sampai kaki langit": "مصاطب خضروات تمتد حتى الأفق",
  "Ranting kopi berbuah di sebuah kebun kopi": "غصن بنّ مثمر في مزرعة بنّ",
  "Ranting kopi berbuah di kebun": "غصن بنّ مثمر في المزرعة",
