  ". Ia memberi tahu pembeli global mana pemasok yang siap masa depan rendah-karbon dan mana yang tidak. Eksportir yang bisa menunjukkan jejak karbon per produk — tertelusur, terverifikasi — justru mendapat keunggulan kompetitif baru.": ". فهو يُعلم المشترين العالميين أي المورّدين جاهز لمستقبل منخفض الكربون وأيهم ليس كذلك. والمصدّرون القادرون على إظهار بصمة كربونية لكل منتج — قابلة للتتبع ومُتحقَّق منها — يكسبون ميزة تنافسية جديدة.",
  ". Izin produk investasi masih dalam kajian.": ". ترخيص منتجات الاستثمار ما يزال قيد الدراسة.",
  ". Justru karena itu batasnya perlu disebut sejelas fiturnya — belum ada pengenalan gambar otomatis, hasilnya selalu rentang dan bukan angka pasti, padanan pohon hanyalah gambaran skala, dan angka IMT bukan nasihat medis. Semuanya ditulis lengkap di pita paling bawah halaman ini, dan diulang di dalam aplikasinya sendiri.": ". ولهذا بالذات ينبغي ذكر الحدود بوضوح الميزات نفسه — لا يوجد بعد تعرّف تلقائي على الصور، والنتيجة دائمًا مدى لا رقمًا قاطعًا، ومعادل الأشجار مجرد تصوّر للمقياس، ورقم مؤشر كتلة الجسم ليس نصيحة طبية. وكل ذلك مكتوب بالكامل في الشريط أسفل هذه الصفحة، ومكرَّر داخل التطبيق نفسه.",
