  "\"Karbon yang bisa diaudit ke sumbernya adalah fondasi ekonomi rendah-karbon yang jujur — dan kami membangunnya untuk dunia.\"": "«الكربون القابل للتدقيق حتى مصدره هو أساس اقتصاد منخفض الكربون صادق — ونحن نبنيه للعالم.»",
  "“Pindai” di Glyiv berarti": "«المسح» في Glyiv يعني",
  "“pindai” di Glyiv berarti mencari barang di pustaka faktor emisi dari namanya": "“المسح” في Glyiv يعني البحث عن الصنف في مكتبة معاملات الانبعاث باسمه",
  "(2018) & ADEME Agribalyse. Dua angka berikut ilustratif ⚠︎, dipakai hanya untuk pratinjau label: harga karbon ≈Rp70.000/tCO₂e, dan serapan 1 pohon dewasa ≈22 kg CO₂ per tahun — keduanya bervariasi menurut pasar, spesies, dan umur tegakan. Semua angka pratinjau — bukan klaim netral karbon, melainkan kontribusi yang bisa dipertanggungjawabkan.": "(2018) و ADEME Agribalyse. الرقمان التاليان توضيحيان ⚠︎، ويُستخدمان لمعاينة البطاقة فقط: سعر الكربون ≈Rp70,000/tCO₂e، وامتصاص 1 شجرة ناضجة ≈22 kg CO₂ في السنة — وكلاهما يتفاوت بحسب السوق والنوع وعمر الغابة. كل الأرقام قيم معاينة — ليست ادعاءً بالحياد الكربوني، بل مساهمة يمكن الدفاع عنها.",
  "(belum termasuk transport/barang/penerbangan); mengabaikan food waste, asal & musim bahan, metode masak. ⚠︎ EF pangan default dari studi global/AS — faktor Indonesia (nasi sebagai staple, lahan gambut) bisa berbeda. Tidak valid untuk anak/hamil/kondisi metabolik khusus. Bukan nasihat medis.": "(لا يشمل بعد النقل/السلع/الرحلات الجوية)؛ ويتجاهل هدر الطعام، ومنشأ المكوّنات وموسمها، وطريقة الطهي. ⚠︎ معاملات انبعاث الغذاء الافتراضية مأخوذة من دراسات عالمية/أمريكية — وقد تختلف المعاملات الإندونيسية (الأرز غذاءً أساسيًا، والأراضي الخثية). غير صالح للأطفال/الحوامل/الحالات الأيضية الخاصة. وليس نصيحة طبية.",
  "(pohon virtual, poin, serta pasar kebutuhan perusahaan yang dibangkitkan sistem — bukan klien dan bukan permintaan nyata). Nilai tutupan yang tampil di peta masih data contoh prototipe; asupan citra satelit rutin, sertifikasi pihak ketiga, dan pencatatan ke registri karbon masih peta jalan. Kontrak ERC-3643 berjalan di jaringan uji, belum jaringan utama.": "(أشجار افتراضية، ونقاط، وسوق احتياجات مؤسسية يولّدها النظام — ليست عملاء ولا طلبًا حقيقيًا). قيم الغطاء النباتي الظاهرة على الخريطة ما زالت بيانات عيّنة لنموذج أولي؛ وتغذية صور الأقمار الصناعية الدورية، والاعتماد من طرف ثالث، والتسجيل في سجل كربوني، كلها ما زالت في خارطة الطريق. عقد ERC-3643 يعمل على شبكة اختبار، لا على الشبكة الرئيسية بعد.",
  "(WHO/IASO/IOTF 2000 — ambang yang juga dipakai materi P2PTM Kemenkes) menurunkan batas risikonya ke 23, karena pada tubuh Asia risiko metabolik naik pada IMT yang lebih rendah. ⚠︎ Sebagian publikasi Kemenkes yang lebih lama memakai pembagian berbeda lagi (17,0 / 18,5 / 25,0 / 27,0), jadi kategori bisa berbeda antar-rujukan.": "(WHO/IASO/IOTF 2000 — وهي العتبة المستخدمة أيضًا في مواد P2PTM لدى Kemenkes) يخفض حدّ الخطورة إلى 23، لأن الخطر الأيضي لدى الأجساد الآسيوية يرتفع عند مؤشر كتلة جسم أدنى. ⚠︎ وبعض منشورات Kemenkes الأقدم تستخدم تقسيمًا آخر (17.0 / 18.5 / 25.0 / 27.0)، لذا قد تختلف الفئة بين المراجع.",
  "% — lebih lebar, mengikuti tier": "% — أوسع، تبعًا للمستوى",
  "% biasanya berarti zona atau kolomnya salah, bukan sertifikatnya. Periksa lagi sebelum memakai batas ini.": "٪ يعني عادةً أن النطاق أو الأعمدة خاطئة، لا الشهادة. تحقّق مرة أخرى قبل استخدام هذا الحد.",
  "% diambil dari tabel tier pustaka Glyiv.": "% مأخوذة من جدول المستويات في مكتبة Glyiv.",
