  "+ berapa pohon untuk menebusnya": "+ كم شجرة لفدائه",
  "+138 ◈ ke dompet mahasiswa · tx 0xabdc930d…2d82": "+138 ◈ إلى محفظة الطالب · tx 0xabdc930d…2d82",
  "= bisa dijelajah sekarang.": "= قابل للاستكشاف الآن.",
  "= dalam pengembangan bertahap. Kami menyatakannya apa adanya, bukan mengklaim yang belum ada.": "= قيد التطوير على مراحل. نقولها كما هي، ولا ندّعي ما لم يوجد بعد.",
  "= pratinjau yang sudah bisa dijelajah, isinya ilustrasi; fitur yang diperagakan di dalamnya belum tentu sudah jadi.": "= معاينة يمكنك استكشافها بالفعل، ومحتواها توضيحي؛ والميزات المعروضة داخلها ليست بالضرورة جاهزة.",
  "= produk yang sudah berjalan dan bisa Anda pakai sendiri, bukan peragaan — sejauh ini hanya": "= منتج قائم بالفعل يمكنك استخدامه بنفسك، لا عرض توضيحي — وحتى الآن فقط",
  "~22 kgCO₂e/pohon/thn ⚠︎": "~22 kgCO₂e/شجرة/سنة ⚠︎",
  "≈ jumlah pohon yang menyerap total ini dalam ~1 tahun (asumsi ~22 kgCO₂e/pohon/tahun ⚠︎). Kontribusi terlacak, bukan klaim netral karbon.": "≈ عدد الأشجار التي تمتص هذا الإجمالي خلال سنة واحدة تقريباً (بافتراض ~22 kgCO₂e لكل شجرة سنوياً ⚠︎). مساهمة متتبَّعة، لا ادعاء بالحياد الكربوني.",
  "● Ilustrasi jaringan karbon · seret untuk memutar": "● توضيح لشبكة الكربون · اسحب للتدوير",
  "⚙️ Setelan": "⚙️ الإعدادات",
  "⚠︎ Agenda riset jangka panjang — belum berjalan, dan belum ada material yang kami jual. Yang kami tuju: riset material alternatif rendah-karbon agar industri memangkas jejaknya dari akar proses, bukan hanya menutupinya.": "⚠︎ أجندة بحثية طويلة الأمد — لم تبدأ بعد، ولا نبيع أي مادة حتى الآن. ما نسعى إليه: بحث في مواد بديلة منخفضة الكربون كي تقلّص الصناعة بصمتها من جذر العملية، لا أن تغطيها فحسب.",
  "⚠︎ Angka fraksi di atas adalah": "⚠︎ أرقام الحصص أعلاه هي",
  "⚠︎ Batang di model ini": "⚠︎ الجذوع في هذا النموذج",
  "⚠︎ BMR di sini": "⚠︎ معدّل الأيض الأساسي هنا",
  "⚠︎ Cabang ini masih": "⚠︎ هذا الفرع ما يزال",
  "⚠︎ Emisi yang dihindari per ton material daur ulang campuran dibanding ditimbun (baseline AS; perlu penyesuaian konteks TPA Indonesia)": "⚠︎ الانبعاثات المتجنَّبة لكل طن من المواد المعاد تدويرها المختلطة مقارنةً بالطمر (خط أساس أمريكي؛ يحتاج تعديلاً لسياق مكبات النفايات في إندونيسيا)",
  "⚠︎ Empat belas petak di peta ini adalah": "⚠︎ القطع الأربع عشرة في هذه الخريطة هي",
  "⚠︎ Estimasi terhindar bersifat ilustrasi & bersumber (kategori). Kontribusi terlacak, bukan klaim netral.": "⚠︎ تقديرات الكربون المتجنَّب توضيحية وموثّقة المصدر (على مستوى الفئة). المساهمة متتبَّعة، وليست ادّعاء حياد.",
  "⚠︎ Estimasi, bukan sertifikasi. Jalur harga (EXIOBASE) paling lemah (sensitif diskon/premium, bisa meleset puluhan %). Berat dari foto rapuh tanpa acuan skala. Database condong Eropa — faktor Indonesia bisa berbeda. Mendukung \"kontribusi/jejak terlacak\" untuk imbalan Glyiv, bukan klaim netral karbon.": "⚠︎ تقدير، لا شهادة اعتماد. مسار السعر (EXIOBASE) هو الأضعف (حسّاس للخصومات/العلاوات، وقد يخطئ بعشرات %). والوزن المستخرج من صورة هشّ بلا مرجع للمقياس. وقاعدة البيانات مائلة نحو أوروبا — وقد تختلف المعاملات الإندونيسية. يدعم \"المساهمة/البصمة المتتبَّعة\" لمكافآت Glyiv، لا ادعاء الحياد الكربوني.",
  "⚠︎ Faktor emisi grid PLN bersifat ilustrasi — di produksi diambil dari data jaringan terkini.": "⚠︎ معامل انبعاث شبكة PLN توضيحي — وفي الإنتاج يُؤخذ من أحدث بيانات الشبكة.",
  "⚠︎ Halaman ini": "⚠︎ هذه الصفحة",
  "⚠︎ Halaman kalkulator Glyiv yang lama (": "⚠︎ صفحة حاسبة Glyiv القديمة (",
  "⚠︎ Ilustrasi rancangan · angka contoh": "⚠︎ رسم توضيحي للتصميم · أرقام نموذجية",
  "⚠︎ Ini": "⚠︎ هذا",
  "⚠︎ Ini alat bantu estimasi, bukan pengukuran instrumen. Akurasinya bergantung pada objek acuan yang sebidang dengan batang dan foto yang diambil tegak lurus. Hasilnya tidak membuat kontribusi apa pun menjadi terverifikasi — verifikasi pihak ketiga masih peta jalan.": "⚠︎ هذه أداة تقدير، وليست قراءة بالأجهزة. تعتمد دقتها على وجود جسم مرجعي في المستوى نفسه للجذع وعلى صورة تُلتقط بشكل عمودي. ولا تجعل النتيجة أي مساهمة موثَّقة — فالتحقق من طرف ثالث ما زال ضمن خارطة الطريق.",
  "⚠︎ Kolom di atas terisi": "⚠︎ الحقول أعلاه مملوءة بـ",
  "⚠︎ Semua hitungan memakai elipsoid WGS84. Sertifikat Indonesia memakai DGN95/SRGI2013, yang di sini diperlakukan sama — selisihnya di bawah ±1 meter, tetapi itu perkiraan, bukan transformasi datum. Untuk batas yang dipersengketakan, angka ini tidak cukup.": "⚠︎ تستخدم جميع الحسابات مجسّم WGS84. أما الشهادات الإندونيسية فتستخدم DGN95/SRGI2013، وتُعامل هنا معاملته نفسها — والفارق دون ±١ متر، لكنه تقريب لا تحويل مرجعي. ولحدٍّ متنازَع عليه لا يكفي هذا الرقم.",
  "⚠︎ Terus terang: vertikal Toko & UMKM masih dalam pengembangan. Kalkulator per item di halaman ini sudah berjalan; program karbon UMKM selengkapnya — pendampingan, laporan berkala, penyaluran offset — masih kami bangun.": "⚠︎ بصراحة: ما زال قطاع المتاجر والمشاريع الصغيرة والمتوسطة قيد التطوير. حاسبة كل صنف في هذه الصفحة تعمل بالفعل؛ أما برنامج الكربون الأوسع للمشاريع الصغيرة والمتوسطة — المرافقة، والتقارير الدورية، وتوجيه التعويضات — فما زلنا نبنيه.",
  "⛭ Kalibrasi ke aktivitas nyata bila tersedia": "⛭ معايرة على نشاط حقيقي عند توفّره",
  "✓ Kamu masuk daftar tunggu! Kami kabari saat fitur pertama siap. 🌿": "✓ أنت الآن في قائمة الانتظار! سنُعلمك حين تجهز الميزة الأولى. 🌿",
