  "Bahan baku (Scope 3) mengalahkan energi: daging sapi ~99 kg CO2e/kg dan kopi ~28 kg CO2e/kg, sementara listrik hanya 0,68 kg CO2e/kWh. Mengganti 30% porsi sapi dengan ayam (~9,9 kg CO2e/kg) atau nabati memangkas jejak lebih besar daripada seluruh penghematan energi gerai. Prioritas: menu engineering & sourcing kopi bersertifikat, baru efisiensi chiller/LED.": "المواد الخام (النطاق 3) تتفوّق على الطاقة: لحم البقر ~99 kg CO2e/kg والقهوة ~28 kg CO2e/kg، بينما الكهرباء 0.68 kg CO2e/kWh فقط. واستبدال 30% من حصة لحم البقر بالدجاج (~9.9 kg CO2e/kg) أو ببدائل نباتية يخفض البصمة أكثر من مجمل وفورات الطاقة في المنفذ. الأولوية: هندسة القائمة وتوريد قهوة معتمَدة، ثم كفاءة المبرّدات وإضاءة LED.",
  "Bahan baku basi & susut": "مواد خام تالفة وهدر",
