  "Bank sampah Glyiv mengubah sampah terpilah menjadi kredit yang bisa ditukar — tercatat rapi per setoran.": "يحوّل Glyiv Waste Bank النفايات المفروزة إلى أرصدة قابلة للاستبدال — مسجَّلة بدقة لكل عملية تسليم.",
  "banyak jalan hijau.": "طرق خضراء كثيرة.",
  "barang yang Anda ketik, karena itu tidak ada tombol kamera — tombol yang menjanjikan pengenalan foto akan menjanjikan kemampuan yang belum kami punya. Hasilnya": "الصنف الذي تكتبه، ولهذا لا يوجد زر كاميرا — فالزر الذي يَعِد بالتعرف على الصور سيَعِد بقدرة لا نملكها بعد. والنتيجة",
  "barang yang Anda pilih. Pengenalan gambar ada di peta jalan — tombolnya akan muncul bersama kemampuannya, bukan sebelum itu.": "الصنف الذي تختاره. التعرّف على الصور ضمن خارطة الطريق — وسيظهر الزر مع القدرة نفسها، لا قبلها.",
  "baris faktor emisi di pustaka Glyiv, dipakai bersama oleh aplikasi ini dan panel outlet — supaya satu barang tidak pernah punya dua angka": "صفوف عوامل الانبعاث في مكتبة Glyiv، يتشاركها هذا التطبيق ولوحة المنفذ — كي لا يحمل صنف واحد رقمين مختلفين أبداً",
  "baris lain.": "أسطر أخرى.",
