  "Berdasarkan pola Anda, dompet menyarankan langkah pengurangan dan opsi kontribusi offset yang sepadan dengan jejak—transparan soal sumber proyek dan jujur soal status verifikasinya (⚠︎ bila belum tersertifikasi).": "بناءً على أنماطك، تقترح المحفظة خطوات للخفض وخيارات مساهمة تعويضية تتناسب مع البصمة—بشفافية عن مصدر المشروع وبصدق عن حالة التحقق منه (⚠︎ إذا لم يكن معتمداً بعد).",
  "Beri pelanggan \"carbon receipt\" & imbalan hijau yang mengunci retensi — komitmen keberlanjutan yang bisa dibuktikan, bukan diklaim.": "امنح العملاء «إيصالاً كربونياً» ومكافآت خضراء تثبّت الولاء — التزام استدامة يمكن إثباته، لا مجرد ادعائه.",
