  "Berkas hanya bisa diunggah setelah Anda masuk. Tabel koordinat di bawah tetap bisa dipakai — batasnya akan tergambar di peta tanpa berkas apa pun.": "لا يمكن رفع الملفات إلا بعد تسجيل الدخول. ويظل جدول الإحداثيات أدناه صالحًا للاستخدام — سيُرسم الحد على الخريطة دون أي ملف.",
