  "brand dan pembeli besar kini menanyakan data keberlanjutan pemasok; tanpa angka, Anda tersisih di tahap awal": "العلامات التجارية وكبار المشترين يسألون اليوم عن بيانات استدامة الموردين؛ وبلا أرقام تُستبعَد في المرحلة الأولى",
  "Buat akun Glyiv": "أنشئ حساب Glyiv",
  "Buat akun, hubungkan sumber data pertama Anda, dan lihat emisinya terlacak sampai ke aktivitas yang menghasilkannya. Uji coba gratis kini terbuka untuk modul outlet (F&B & Ritel): 30 hari atau 500 transaksi, mana yang lebih dulu. Untuk industri lain, bicara dulu dengan tim kami. Butuh metodologi lengkapnya? Whitepaper tersedia di bawah NDA.": "أنشئ حسابًا، واربط أول مصدر بيانات لديك، وشاهد الانبعاثات متتبَّعة حتى النشاط الذي أنتجها. التجربة المجانية متاحة الآن لوحدة المنافذ (الأغذية والمشروبات والتجزئة): 30 يومًا أو 500 معاملة، أيهما أسبق. أما القطاعات الأخرى فتحدَّث أولًا مع فريقنا. تحتاج المنهجية كاملة؟ الورقة البيضاء متاحة بموجب اتفاقية عدم إفشاء (NDA).",
  "Building the Digital Ecosystem for Sustainable Living": "نبني النظام البيئي الرقمي لحياة مستدامة",
  "Building the digital ecosystem for sustainable living.": "نبني النظام البيئي الرقمي لحياة مستدامة.",
  "Buka aplikasinya dan cari satu barang yang tadi Anda beli. Angka pertamanya muncul tanpa perlu mendaftar lebih dulu.": "افتح التطبيق وابحث عن صنف واحد اشتريته للتو. يظهر الرقم الأول دون الحاجة إلى التسجيل مسبقاً.",
  "Buka di peta": "افتح في الخرائط",
  "Buka Glyiv Hijau": "افتح Glyiv Green Assets",
  "Buka Green Assets →": "افتح Green Assets →",
  "Buka Green Assets untuk menggambar batas sebuah petak dan melihat luas serta estimasi serapannya, atau lihat peta petak contoh lebih dulu. Pendaftaran pemilik lahan": "افتح Green Assets لرسم حدود قطعة أرض والاطلاع على مساحتها وتقدير امتصاصها، أو اطّلع أولًا على خريطة القطع النموذجية. أما تسجيل ملّاك الأراضي",
  "Buka Green Intelligence Platform →": "افتح Green Intelligence Platform →",
  "Buka halaman ini": "افتح هذه الصفحة",
  "Buka halaman publik": "افتح الصفحة العامة",
  "Buka Kabar →": "افتح Glyiv News →",
  "Buka pratinjau": "افتح المعاينة",
  "Buka pratinjaunya, atau mulai dari kalkulator IMT — lalu lihat bagaimana satu kebiasaan sehat bisa membuat jejak Anda lebih ringan, dan terlacak.": "افتح المعاينة، أو ابدأ من حاسبة مؤشر كتلة الجسم — ثم انظر كيف يمكن لعادة صحية واحدة أن تجعل بصمتك أخف، ومتتبَّعة.",
  "Buka pratinjaunya: satu kuis literasi karbon, satu gambaran jejak Anda, dan arah yang sedang kami bangun untuk mengubahnya jadi aksi yang terlacak.": "افتح المعاينة: اختبار واحد في الثقافة الكربونية، وصورة واحدة لبصمتك، والاتجاه الذي نبنيه لتحويلها إلى عمل متتبَّع.",
  "Buka pratinjaunya: seperti apa jadinya bila tiap keranjang belanja menjadi keputusan iklim — jejaknya terlihat, dan bisa diimbangi saat checkout.": "افتح المعاينة: كيف يبدو الأمر حين تصبح كل سلة تسوّق قراراً مناخياً — بصمتها ظاهرة، ويمكن موازنتها عند الدفع.",
  "Buka Scan Karbon lengkap (foto, login, dompet) →": "افتح مسح الكربون الكامل (صورة، تسجيل دخول، محفظة) →",
  "Buka semua bagian": "فتح كل الأقسام",
  "Buka Tree Marketplace →": "افتح Tree Marketplace →",
  "bukan admin Kabar. Masuk dengan akun admin Glyiv yang berwenang.": "ليس مسؤول Kabar. سجّل الدخول بحساب مسؤول Glyiv مخوَّل.",
  "bukan cuma laporannya.": "ليس التقرير وحده.",
