  "digambar sebagai nol — lupa mencatat tidak sama dengan tidak ada emisi, dan grafik yang menukar keduanya akan berbohong tanpa satu pun kalimat bohong.": "مرسومًا كصفر — فنسيان التسجيل ليس كانعدام الانبعاثات، والرسم البياني الذي يخلط بينهما سيكذب دون أن ينطق بجملة كاذبة واحدة.",
  "Digital sepenuhnya,": "رقمي بالكامل،",
  "dihitung dengan faktor emisi grid Indonesia terkini yang bersumber jelas, selaras GHG Protocol Scope 1-2-3; metodologi dirinci di whitepaper kami di bawah NDA": "محسوبة بأحدث عوامل انبعاث الشبكة الإندونيسية وواضحة المصدر، بما يتوافق مع GHG Protocol للنطاقات 1-2-3؛ والمنهجية مفصّلة في ورقتنا البيضاء بموجب اتفاقية عدم إفشاء",
  "dihitung selaras GHG Protocol & ISO 14064, lengkap dengan jejak audit yang bisa langsung diserahkan ke merek pembeli": "محسوب بما يتوافق مع GHG Protocol وISO 14064، مع مسار تدقيق يمكن تسليمه مباشرةً للعلامة المشترية",
