  "Intelijen karbon bukan hanya untuk korporasi. Hitung jejakmu dari gaya hidup (IMT/diet), atau": "ذكاء الكربون ليس للشركات وحدها. احسب بصمتك من نمط حياتك (مؤشر كتلة الجسم/النظام الغذائي)، أو",
  "Intelijen karbon yang jujur": "ذكاء كربوني صادق",
  "Intensitas karbon per kWh": "كثافة الكربون لكل kWh",
  "Intensitas karbon per outlet · ilustrasi, angka contoh": "كثافة الكربون لكل منفذ · توضيحي، أرقام نموذجية",
  "Intensitas karbon tinggi menyembunyikan uang yang bocor tiap hari. Tungku RKEF berbahan batu bara rata-rata melepas sekitar 45 ton CO2 per ton nikel, lebih dari tiga kali lipat jalur pengolahan MHP/HPAL, dan setiap ton CO2 berlebih itu adalah bahan bakar yang terbeli namun terbuang, bukan logam yang terjual. Ketika karbon dipetakan per lini, per tungku, dan per shift, terlihat di mana energi hangus percuma, di mana idle-load menyala tanpa produksi, dan di mana pembeli mulai menahan premium. Selisih intensitas inilah yang menentukan apakah Anda dibeli dengan harga penuh atau didiskon sebagai 'high-carbon supply'.": "الكثافة الكربونية العالية تُخفي أموالًا تتسرّب كل يوم. فأفران RKEF العاملة بالفحم تُطلق في المتوسط نحو 45 طنًا من CO2 لكل طن نيكل، أي أكثر من ثلاثة أضعاف مسار المعالجة MHP/HPAL، وكل طن CO2 زائد هو وقود اشتُري ثم أُهدر، لا معدن بيع. وحين تُرسم خريطة الكربون لكل خط ولكل فرن ولكل وردية، يتبيّن أين تحترق الطاقة سُدىً، وأين يعمل الحمل الخامل بلا إنتاج، وأين بدأ المشترون يحجبون العلاوة. وهذا الفارق في الكثافة هو ما يحدّد ما إذا كنت ستُشترى بالسعر الكامل أم بخصم بوصفك «إمدادًا عالي الكربون».",
  "Intensitas per 1.000 kkal belum ada di pustaka faktor emisi Glyiv.": "الكثافة لكل 1,000 سعرة حرارية غير متوفرة بعد في مكتبة معاملات الانبعاث لدى Glyiv.",
