  "Jalan di perangkat yang sudah ada. Outlet langsung mulai membangun jejak karbon per outlet.": "يعمل على الأجهزة الموجودة لديك. تبدأ المنافذ فورًا في بناء بصمة كربونية لكل منفذ.",
