  "keluarkan angka emisi per pelanggan sebagai nilai jual 'low-carbon cloud' dalam tender — plus opsi kontribusi offset tertokenisasi untuk sisa emisi": "أصدر أرقام الانبعاثات لكل عميل كنقطة بيع «سحابة منخفضة الكربون» في المناقصات — إضافة إلى خيار مساهمة تعويضية مرمَّزة للانبعاثات المتبقية",
  "Kemasan makanan hari ini rapi mencantumkan harga dan kalori, tapi hampir tak pernah dampak iklimnya. Padahal sistem pangan menyumbang sekitar seperempat emisi gas rumah kaca global, dan pilihan di piring — nabati atau daging, lokal atau impor — bisa berbeda berkali-kali lipat. Sinyal itu hilang tepat saat keputusan dibuat.": "تعرض أغلفة الأغذية اليوم السعر والسعرات بدقة، لكنها لا تكاد تعرض الأثر المناخي أبدًا. مع أن النظم الغذائية تمثّل نحو ربع انبعاثات غازات الدفيئة عالميًا، وأن الخيار في الطبق — نباتي أو لحم، محلي أو مستورد — قد يتفاوت أضعافًا. تغيب تلك الإشارة في اللحظة نفسها التي يُتخذ فيها القرار.",
  "Kembali ke beranda": "العودة إلى الرئيسية",
