  "Makin besar batang dan acuan di dalam foto, makin kecil galat per piksel saat Anda menandai titiknya. Mundur hanya secukupnya.": "كلما كبر الجذع والجسم المرجعي داخل الصورة، صغر الخطأ لكل بكسل عند تحديد النقاط. تراجَع بالقدر اللازم فقط.",
  "Mandat yang hilang": "تفويضات ضائعة",
  "Mangrove, hutan kota, rehabilitasi hutan, atau agroforestri bersama petani — semuanya punya koordinat.": "أشجار المانغروف، والغابات الحضرية، وإعادة تأهيل الغابات، أو الزراعة الحرجية مع المزارعين — لكلٍّ منها إحداثيات.",
  "Manufaktur menghubungkan ratusan pemasok menjadi satu produk, dan di situlah beban karbon terbesarnya bersembunyi. ⚠︎ Halaman ini memaparkan": "يربط التصنيع مئات المورّدين في منتج واحد، وهناك يختبئ أكبر أعبائه الكربونية. ⚠︎ تعرض هذه الصفحة",
  "Manufaktur menghubungkan ratusan pemasok menjadi satu produk, dan di situlah beban karbon terbesarnya bersembunyi. Bagi kebanyakan perusahaan manufaktur, emisi Scope 3 (rantai pasok) mencakup 70–90% dari total jejak karbon — jauh melampaui emisi pabrik sendiri. Merek global yang menjadi pembeli Anda kini menagih data karbon produk kepada seluruh pemasoknya. Pemasok yang bisa menyerahkan angka karbon per produk yang kredibel naik ke daftar preferred supplier; yang belum bisa, pelan-pelan tergeser. Mengelola karbon rantai pasok sudah menjadi syarat untuk tetap berada di dalam rantai pasok global itu sendiri. Rancangan modul inilah yang sedang kami bangun.": "تربط الصناعة التحويلية مئات الموردين في منتج واحد، وهناك يختبئ أثقل أعبائها الكربونية. فلدى معظم شركات التصنيع، تشكّل انبعاثات النطاق 3 (سلسلة التوريد) 70–90% من إجمالي البصمة الكربونية — بما يفوق كثيرًا انبعاثات المصنع نفسه. والعلامات العالمية التي تشتري منك تطالب اليوم كل مورّديها ببيانات كربون المنتج. فالموردون القادرون على تقديم أرقام كربون موثوقة لكل منتج يصعدون إلى قائمة الموردين المفضّلين؛ ومن لا يستطيع يُزاح تدريجيًا. لقد صارت إدارة كربون سلسلة التوريد شرطًا للبقاء داخل تلك السلسلة العالمية نفسها. وهذا هو تصميم الوحدة الذي نبنيه الآن.",
