  "Masuk daftar tunggu — kami kabari saat fitur pertama (Tree Marketplace, wallet, scan karbon) siap kamu coba.": "انضم إلى قائمة الانتظار — سنخبرك عندما تصبح الميزات الأولى (Tree Marketplace، المحفظة، مسح الكربون) جاهزة للتجربة.",
  "Masuk daftar tunggu — kami kabari saat gelombang tantangan berikutnya dibuka. Gratis, dari HP.": "انضم إلى قائمة الانتظار — سنخبرك عند فتح الموجة التالية من التحدي. مجانًا، من هاتفك.",
