  "Masuk ke dompet Green Assets yang sama dengan aplikasi Hijau, dan langsung bisa dibelanjakan di katalog perlengkapan perawatan. Maksimal 20 pengukuran berpoin per hari ⚠︎ — batas itu ditegakkan di aplikasi ini saja, bukan di server.": "تدخل في محفظة Glyiv Green Assets نفسها المستخدمة في تطبيق Hijau، ويمكن إنفاقها مباشرة في كتالوج معدات العناية. بحد أقصى 20 قياسًا مكسبًا للنقاط يوميًا ⚠︎ — وهذا الحد مطبَّق داخل هذا التطبيق فقط، لا على الخادم.",
  "Masuk ke laporan Anda?": "هل يدخل في تقريرك؟",
  "Masuk sekali, lalu pilih cabang & ajukan aksesnya dari dasbor — mis. minta uji coba Glyiv Outlet.": "سجِّل الدخول مرة واحدة، ثم اختر الفرع واطلب صلاحية الوصول إليه من لوحة التحكم — مثلًا طلب تجربة Glyiv Outlet.",
  "Masuk untuk melanjutkan": "سجِّل الدخول للمتابعة",
