  "Masuk untuk menyimpan kredit & riwayat scan.": "سجّل الدخول لحفظ الأرصدة وسجل عمليات المسح.",
  "masukkan data kendaraan & konsumsi bahan bakar — Glyiv menghitung emisi Scope 1 per kendaraan dan per rute secara otomatis": "أدخِل بيانات المركبات واستهلاك الوقود — ويحسب Glyiv انبعاثات Scope 1 لكل مركبة ولكل مسار تلقائيًا",
  "Masukkan koordinat di atas & tekan": "أدخِل الإحداثيات أعلاه واضغط",
  "Masukkan sampah — kamera akan mengenalinya": "أدخل النفايات — ستتعرف عليها الكاميرا",
  "Material afkir di lini 2 naik diam-diam": "المواد المرفوضة في الخط 2 ترتفع بهدوء",
  "Material rendah-karbon →": "مواد منخفضة الكربون →",
  "material yang dipakai": "المواد المستخدمة",
  "material yang lebih baik.": "مواد أفضل.",
  "Matikan alat & lampu yang tak dipakai": "أطفئ الأجهزة والمصابيح غير المستخدمة",
  "Meja ini ditahan untuk Anda selama 15 menit. Selesaikan pembayaran lebih dulu, lalu tekan tombol di bawah supaya outlet memeriksanya.": "هذه الطاولة محجوزة لك لمدة ١٥ دقيقة. أكمل الدفع أولًا، ثم اضغط الزر أدناه ليتحقق منه المنفذ.",
  "Meja ini sedang dipesan orang lain. Pilih meja lain, atau datang langsung ke outlet.": "هذه الطاولة قيد الحجز من شخص آخر. اختر طاولة أخرى، أو تفضّل بالحضور مباشرةً.",
  "Meja terpilih": "الطاولة المختارة",
  "Meja yang sudah terbooking": "الطاولات المحجوزة",
  "mekanisme pasar karbon Perjanjian Paris yang membuka pembiayaan iklim internasional bagi pemda dengan MRV kredibel": "آلية سوق الكربون في اتفاق باريس التي تفتح التمويل المناخي الدولي أمام الحكومات المحلية ذات MRV موثوق",
  "Melacak karbon menyorot kebocoran biaya itu.": "تتبع الكربون يسلط الضوء على ذلك التسرب في الكلفة.",
  "Melacak karbon menyorot kebocoran biaya yang tak pernah masuk anggaran — energi yang terbuang, bahan yang menyusut, rute yang berputar — lalu menunjukkan cara menutupnya. Disusun selaras GHG Protocol & ISO 14064, dengan solusi yang berbeda untuk tiap industri. Sertifikasi dan MRV pihak ketiga masih peta jalan; yang kami berikan hari ini adalah angka yang": "تتبُّع الكربون يكشف تسرُّبات التكلفة التي لا تدخل الموازنة قط — طاقة مهدورة، ومواد تتناقص، ومسارات تلتفّ — ثم يبيّن كيف تُسدّ. مبنيّ بما يتوافق مع GHG Protocol و ISO 14064، بحلّ مختلف لكل قطاع. الاعتماد والتحقق MRV من طرف ثالث ما زالا في خارطة الطريق؛ وما نقدّمه اليوم هو أرقام",
  "Melacak karbon menyoroti kebocoran uang yang selama ini dianggap 'biaya operasional wajar'. Di sawit, sumber terbesar sering tersembunyi di tiga tempat: emisi metana dari kolam limbah pabrik (POME) yang sebenarnya bisa ditangkap dan dipakai sebagai biogas untuk menekan pembelian bahan bakar; boros solar pada genset dan angkutan TBS karena rute serta beban mesin tak terpantau; dan yang paling mahal — kehilangan premium ekspor serta akses pembiayaan hijau karena tidak bisa menunjukkan status bebas deforestasi. Ketika semua terlacak dalam satu dasbor, angka-angka ini berubah dari 'biaya tak terlihat' menjadi daftar peluang penghematan yang bisa dihitung.": "تتبُّع الكربون يُبرز أموالًا تتسرّب ظلّت طويلًا تُعدّ «تكلفة تشغيل معقولة». ففي زيت النخيل، تختبئ أكبر المصادر غالبًا في ثلاثة مواضع: انبعاثات الميثان من أحواض مخلّفات المصنع السائلة (POME) التي يمكن في الواقع التقاطها واستخدامها غازًا حيويًا لخفض مشتريات الوقود؛ وإسراف الديزل في المولّدات وفي نقل عناقيد الثمار الطازجة بسبب عدم مراقبة المسارات وأحمال المحرّكات؛ والأغلى ثمنًا — فقدان علاوة التصدير والوصول إلى التمويل الأخضر لتعذُّر إثبات الخلوّ من إزالة الغابات. وحين يصبح ذلك كله متتبَّعًا في لوحة واحدة، تتحوّل هذه الأرقام من «تكاليف غير مرئية» إلى قائمة فرص توفير قابلة للحساب.",
  "Memakai aplikasi Glyiv — berkas APK maupun versi webnya — berarti Anda menyetujui kedua dokumen di bawah, termasuk bahwa data Anda kami kelola sebagaimana tertulis di sana. Keduanya bisa dibaca siapa saja tanpa masuk, dan masing-masing punya nomor versi serta tanggal berlaku yang terlihat di layar.": "استخدام تطبيق Glyiv — سواء ملف APK أو نسخته على الويب — يعني موافقتك على المستندين أدناه، بما في ذلك أننا نتعامل مع بياناتك بالطريقة المكتوبة فيهما. ويمكن لأي شخص قراءتهما دون تسجيل الدخول، ولكلٍّ منهما رقم إصدار وتاريخ سريان ظاهران على الشاشة.",
  "Memakainya tanpa internet": "استخدامه بدون إنترنت",
  "memandu setiap keputusan.": "يوجّه كل قرار.",
  "memantau petak Anda.": "يراقب قطعتك.",
