  "Membuka percakapan awal dengan jaringan & calon mitra strategis di Eropa — menjembatani metodologi Glyiv ke standar dan pasar global.": "يفتح المحادثات الأولى مع الشبكات والشركاء الاستراتيجيين المحتملين في أوروبا — جسراً بين منهجية Glyiv والمعايير والأسواق العالمية.",
  "memenuhi syarat tender yang meminta jejak terlacak": "تستوفي شرط مناقصة يطلب بصمة متتبَّعة",
  "Memimpin produk, strategi, dan eksekusi Glyiv — dengan keyakinan bahwa data karbon paling jujur lahir di titik transaksi.": "يقود منتج Glyiv واستراتيجيته وتنفيذه — بقناعة أن أصدق بيانات الكربون تولد عند نقطة المعاملة.",
  "Memindai barang dan menghitung IMT tetap bisa dipakai tanpa masuk — yang butuh akun hanya menyimpan hasilnya.": "مسح المنتجات وحساب مؤشر كتلة الجسم يعملان دون تسجيل الدخول — الحساب مطلوب فقط لحفظ النتائج.",
  "meminta datanya, bukan hanya minyaknya": "يطلبون البيانات، لا الزيت وحده",
  "Mempertajam strategi, inovasi, dan daya saing — memastikan setiap keputusan produk berpijak pada data dan kebutuhan nyata pengguna.": "يشحذ الاستراتيجية والابتكار والقدرة التنافسية — ويضمن أن يستند كل قرار منتج إلى البيانات وإلى احتياجات المستخدمين الحقيقية.",
