  "UU HPP 2021 menetapkan tarif pajak karbon minimal Rp30.000 per ton untuk PLTU batu bara. Tapi tanggal berlakunya terus digeser — dan hingga kini ⚠︎ belum efektif berjalan.": "يحدد قانون HPP لعام 2021 حدًا أدنى لضريبة الكربون قدره Rp30,000 للطن على محطات الطاقة العاملة بالفحم. لكن تاريخ سريانه يُؤجَّل باستمرار — وحتى الآن ⚠︎ لم يدخل حيّز التنفيذ فعليًا.",
