  "Visi · belum dibangun": "رؤية · لم تُبنَ بعد",
  "Visi appchain khusus sebagai registry karbon: biaya rendah, throughput tinggi, standar MRV tertanam sejak protokol. Masih arah — belum ada whitepaper teknis, testnet, atau kode. Jalur realistis kini: bangun di atas Ethereum dulu.": "رؤية سلسلة تطبيقات مخصصة كسجل كربوني: تكلفة منخفضة، وإنتاجية عالية، ومعايير MRV مضمَّنة في البروتوكول نفسه. لا تزال اتجاهاً — فلا وجود بعد لورقة تقنية أو شبكة اختبار أو شيفرة. والمسار الواقعي الآن: البناء فوق Ethereum أولاً.",
  "Visi Tree Marketplace: kepemilikan aset hijau dunia-nyata yang bisa dibagi hingga": "رؤية Tree Marketplace: ملكية أصول خضراء من العالم الحقيقي قابلة للتجزئة حتى",
  "Waktu idle mesin saat menunggu bongkar-muat": "زمن دوران المحرك على الفراغ أثناء انتظار التحميل والتفريغ",
  "Waktu tahanan habis sebelum pembayaran diperiksa, jadi mejanya dilepas kembali.": "انتهت مدة الحجز قبل التحقق من الدفع، لذا أُفرج عن الطاولة.",
  "Wawasan karbon mingguan, tanpa jargon — lewat Kabar.": "رؤى كربونية أسبوعية بلا مصطلحات معقدة — عبر Kabar.",
  "weighted average carbon intensity & financed emissions per emiten, sektor, dan dana — mengikuti kerangka PCAF & IFRS S2": "متوسط كثافة الكربون المرجّح والانبعاثات المموَّلة لكل مُصدِر وقطاع وصندوق — وفق إطاري PCAF وIFRS S2",
  "Weighted-average carbon intensity (WACI) portofolio investasi mendominasi >99% jejak — operasional kantor nyaris tak relevan. Merotasi ~10% AUM dari sektor fosil ke green/sustainability bonds dapat memangkas jejak terbiayai ~15-30% tanpa mengubah profil risiko-return secara material. Laporkan per PCAF & TCFD/ISSB, dan lacak per-emiten (data quality score) alih-alih rata-rata sektor.": "يهيمن متوسط كثافة الكربون المرجّح (WACI) لمحفظة الاستثمار على أكثر من 99% من البصمة — أما عمليات المكتب فتكاد لا تكون ذات صلة. وتدوير نحو 10% من الأصول المُدارة من قطاعات الوقود الأحفوري إلى سندات خضراء/سندات استدامة قد يخفض البصمة المموَّلة بنحو 15-30% دون تغيير جوهري في ملف المخاطرة والعائد. وأبلغ وفق PCAF وTCFD/ISSB، وتتبّع لكل جهة مصدِرة (درجة جودة البيانات) بدلًا من متوسطات القطاع.",
