  "yang paling kecil.": "الأصغر.",
  "Yang perlu Anda minta kepada kami": "ما يلزم أن تطلبه منا",
  "yang selalu ditampilkan sebagai rentang beserta tier datanya; ia bukan pengukuran dan bukan hasil verifikasi pihak ketiga, dan sertifikasi/MRV/registri tetap peta jalan. Padanan pohon adalah": "الذي يُعرض دائمًا كنطاق مع مستوى جودة بياناته؛ فهو ليس قياسًا ولا نتيجة تحقق من طرف ثالث، ويبقى الاعتماد وMRV والسجل ضمن خارطة الطريق. ومعادل الشجرة هو",
  "Yang sering terlewat: CBAM bukan sekadar biaya kepatuhan, tapi": "ما يُغفَل غالبًا: CBAM ليس مجرد كلفة امتثال، بل",
  "Yang sudah bisa dipakai sekarang adalah alat pemantauannya: gambar batas sebuah petak, lihat luas terhitung dan estimasi serapan berentang ⚠︎, lalu simpan ke daftar pantauan Anda. Sisanya — pohon virtual, poin, dan pasar kebutuhan perusahaan — adalah simulasi yang ditandai jelas di dalam aplikasi. Sertifikasi pihak ketiga serta pencatatan ke registri karbon (SRN-PPI, IDXCarbon, Verra) masih peta jalan ⚠︎.": "المتاح للاستخدام الآن هو أداة الرصد: ارسم حدود قطعة أرض، وشاهد المساحة المحسوبة وتقدير امتصاص بمدى ⚠︎، ثم احفظها في قائمة المتابعة لديك. أما البقية — الأشجار الافتراضية، والنقاط، وسوق احتياجات الشركات — فهي محاكاة موسومة بوضوح داخل التطبيق. ولا تزال شهادات الطرف الثالث والقيد في سجلات الكربون (SRN-PPI، IDXCarbon، Verra) في خارطة الطريق ⚠︎.",
