  "Simpan perubahan": "حفظ التغييرات",
  "Jam boleh dikosongkan untuk kabar yang bukan acara — promo atau pengumuman, misalnya. Jam selesai baru bisa diisi sesudah jam mulai terisi, dan ia harus lebih malam daripada jam mulai.": "يمكن ترك الوقت فارغًا للأخبار التي ليست فعالية — عرض ترويجي أو إعلان مثلًا. لا يمكن إدخال وقت الانتهاء إلا بعد إدخال وقت البدء، ويجب أن يكون بعده.",
  "Kabar berjenis “aktivitas hijau” tampil di halaman publik dengan keterangan bahwa ia dilaporkan sendiri oleh outlet dan belum diverifikasi Glyiv. Keterangan itu ditulis otomatis dan tidak bisa dimatikan — ini produk iklim, dan klaim lingkungan yang tampak resmi tanpa keterangan asalnya adalah risiko nyata bagi Anda maupun kami.": "تظهر الأخبار من نوع «نشاط أخضر» في الصفحة العامة مع ملاحظة تفيد بأن المنفذ أبلغ عنها بنفسه وأن Glyiv لم تتحقق منها. تُكتب هذه الملاحظة تلقائيًا ولا يمكن إيقافها — هذا منتج مناخي، والادعاء البيئي الذي يبدو رسميًا دون ذكر مصدره خطر حقيقي عليك وعلينا.",
  "Jam mulai harus berbentuk 19:00.": "يجب أن يكون وقت البدء بصيغة 19:00.",
  "Jam selesai harus berbentuk 22:00.": "يجب أن يكون وقت الانتهاء بصيغة 22:00.",
  "Isi jam mulai dulu sebelum jam selesai.": "أدخل وقت البدء قبل وقت الانتهاء.",
  "Jam selesai harus sesudah jam mulai.": "يجب أن يكون وقت الانتهاء بعد وقت البدء.",
  "Ketik nama satu barang — kopi, telur, nasi — lalu Glyiv mencarinya di pustaka faktor emisi dan menghitung estimasinya, tanpa akun dan tanpa mendaftar. (“Pindai” di Glyiv berarti mencari di pustaka; pengenalan": "اكتب اسم صنف واحد — قهوة أو بيض أو أرز — ثم يبحث عنه Glyiv في مكتبة معاملات الانبعاثات ويحسب التقدير، دون حساب ودون تسجيل. («المسح» في Glyiv يعني البحث في المكتبة؛ أما التعرف على",
  "barang lewat kamera masih peta jalan, belum ada.) Akun baru diperlukan kalau Anda ingin catatan hariannya tersimpan dan bisa dibuka lagi besok.": "الأصناف عبر الكاميرا فما زال ضمن خارطة الطريق ولم يتوفر بعد.) لا يلزم الحساب إلا إذا أردت حفظ السجل اليومي وفتحه مجددًا غدًا.",
  "Riwayat butuh akun": "يحتاج السجل إلى حساب",
