  "Komposter & jemput terjadwal": "حاويات تسميد وجمع مجدول",
  "Komposter & jemput terjadwal →": "حاويات تسميد وجمع مجدول →",
  "Sampah Rumah Tangga": "نفايات منزلية",
  "Scan & catat harian · sudah jalan": "مسح وتسجيل يومي · يعمل بالفعل",
  "Iklim berubah di atmosfer.": "المناخ يتغيّر في الغلاف الجوي.",
  "Tagihannya turun ke dompet.": "والفاتورة تصل إلى جيبك.",
  "Perjanjian Paris 2015 kini mengikat 194 Pihak pada satu janji: menahan pemanasan jauh di bawah 2°C, dan mengupayakan 1,5°C. Rata-rata suhu global 2023-2025 sudah 1,48°C di atas era pra-industri, jadi ambang itu bukan lagi hal yang ditunggu, ia sedang disentuh.": "اتفاق باريس 2015 يُلزِم اليوم 194 طرفًا بوعد واحد: إبقاء الاحترار دون درجتين مئويتين بكثير، والسعي إلى 1.5 درجة. متوسط الحرارة العالمي بين 2023 و2025 بلغ بالفعل 1.48 درجة فوق مستويات ما قبل الصناعة، لذا لم تعد هذه العتبة أمرًا ننتظره، بل نلامسه الآن.",
  "Lewat Perjanjian Paris, dunia sepakat menahan pemanasan jauh di bawah 2°C. Rata-rata suhu global 2023-2025 sudah 1,48°C — ambang itu bukan lagi hal yang ditunggu.": "عبر اتفاق باريس، اتفق العالم على إبقاء الاحترار دون درجتين مئويتين بكثير. ومتوسط الحرارة العالمي بين 2023 و2025 بلغ بالفعل 1.48 درجة — لم تعد هذه العتبة أمرًا ننتظره.",
  "Panen menipis, jam kerja lapangan berkurang, harga pangan terdorong naik. Yang berubah bukan grafik: belanja, penghasilan, dan rasa aman pekerjaan.": "المحاصيل تتراجع، وساعات العمل الميداني تتقلّص، وأسعار الغذاء تُدفع إلى الأعلى. ما يتغيّر ليس رسمًا بيانيًا: بل التسوّق والدخل والأمان الوظيفي.",
  "Glyiv adalah ekosistem digital ekonomi hijau.": "Glyiv هي المنظومة الرقمية للاقتصاد الأخضر.",
  "Kami menyambung pilihan harian, usaha kecil, lahan, dan modal — supaya yang lebih hijau juga masuk akal secara ekonomi. Di Indonesia, ekonomi hijau diperkirakan membuka 15,3 juta pekerjaan pada 2045 ⚠︎. Jalannya kami buka untuk orang biasa, bukan hanya korporasi.": "نربط الخيارات اليومية والأعمال الصغيرة والأراضي ورأس المال — كي يصبح الخيار الأكثر خضرة منطقيًا اقتصاديًا أيضًا. في إندونيسيا، يُقدَّر أن يفتح الاقتصاد الأخضر 15.3 مليون وظيفة بحلول 2045 ⚠︎. ونحن نفتح هذا الطريق للناس العاديين، لا للشركات وحدها.",
  "Suhu naik, ekonomi menyusut.": "ترتفع الحرارة، ويتقلّص الاقتصاد.",
  "Pada jalur emisi tinggi, PDB Asia-Pasifik berkembang diproyeksikan 17% lebih rendah pada 2070 ⚠︎. Untuk Indonesia, pemerintah memperkirakan kerugian iklim menekan PDB 0,66-3,45% pada 2030 ⚠︎, dan Bappenas memproyeksikan kerugian tahunannya naik sekitar empat kali lipat antara 2025 dan 2029 bila tidak ada yang berubah ⚠︎.": "على مسار الانبعاثات المرتفعة، يُتوقع أن يكون الناتج المحلي في آسيا والمحيط الهادئ النامية أقل بنسبة 17% بحلول 2070 ⚠︎. وفي إندونيسيا تقدّر الحكومة خسائر مناخية تضغط على الناتج المحلي بنسبة 0.66-3.45% في 2030 ⚠︎، وتتوقع بابيناس تضاعف الخسائر السنوية أربع مرات تقريبًا بين 2025 و2029 إن لم يتغيّر شيء ⚠︎.",
  "Persen terasa jauh sampai diterjemahkan. Panas menekan panen: tekanan harga pangan diproyeksikan naik 0,92-3,23 poin persen per tahun pada 2035 ⚠︎. Panas juga memangkas jam kerja, setara 80 juta pekerjaan penuh waktu pada 2030 ⚠︎, dan 60% bebannya jatuh ke pertanian. Yang berubah bukan grafik: belanja, penghasilan, dan rasa aman pekerjaan.": "تبدو النسب بعيدة حتى تُترجم. الحرارة تضغط على المحاصيل: يُتوقع أن يرتفع ضغط أسعار الغذاء بين 0.92 و3.23 نقطة مئوية سنويًا بحلول 2035 ⚠︎. كما تقتطع الحرارة من ساعات العمل ما يعادل 80 مليون وظيفة بدوام كامل بحلول 2030 ⚠︎، ويقع 60% من هذا العبء على الزراعة. ما يتغيّر ليس رسمًا بيانيًا: بل التسوق والدخل والأمان الوظيفي.",
  "Karena itu Glyiv bukan aplikasi karbon.": "لهذا فإن Glyiv ليس تطبيق كربون.",
  "Kami membangun ekosistem ekonomi hijau: menyambung pilihan harian, usaha kecil, lahan, dan modal, supaya pilihan yang lebih hijau juga masuk akal secara ekonomi. Ekonomi hijau diperkirakan membuka 15,3 juta pekerjaan di Indonesia pada 2045 ⚠︎, dan kami ingin jalan ke sana bisa ditempuh orang biasa, bukan hanya korporasi.": "نحن نبني منظومة اقتصاد أخضر: تربط الخيارات اليومية والأعمال الصغيرة والأراضي ورأس المال، حتى يصبح الخيار الأكثر خضرة منطقيًا اقتصاديًا أيضًا. يُقدَّر أن يفتح الاقتصاد الأخضر 15.3 مليون وظيفة في إندونيسيا بحلول 2045 ⚠︎، ونريد أن يكون الطريق إلى هناك في متناول الناس العاديين، لا الشركات الكبرى وحدها.",
  "Tanda ⚠︎ berarti proyeksi: kemungkinan, bukan kejadian.": "علامة ⚠︎ تعني إسقاطًا: احتمالًا، لا واقعة.",
