  "Jalur emisi tinggi": "مسار الانبعاثات المرتفعة",
  "Geser sendiri, atau biarkan ia bergerak.": "حرّكه بنفسك، أو دعه يتحرك وحده.",
  "Angka yang dijanjikan Perjanjian Paris. Rata-rata global 2023-2025 sudah 1,48°C. Pada 2030, panas diproyeksikan menghapus 2,2% jam kerja dunia ⚠︎.": "الرقم الذي وعد به اتفاق باريس. متوسط الحرارة العالمي بين 2023 و2025 بلغ 1.48 درجة. وبحلول 2030 يُتوقع أن تمحو الحرارة 2.2% من ساعات العمل في العالم ⚠︎.",
  "Batas atas yang disepakati dunia. Pemerintah memperkirakan kerugian iklim menekan PDB Indonesia 0,66-3,45% pada 2030 ⚠︎. Yang menyusut lebih dulu: panen, jam kerja lapangan, daya beli.": "الحد الأعلى الذي اتفق عليه العالم. تقدّر الحكومة خسائر مناخية تضغط على الناتج المحلي الإندونيسي بنسبة 0.66-3.45% في 2030 ⚠︎. وأول ما يتقلّص: المحاصيل وساعات العمل الميداني والقدرة الشرائية.",
  "Jalur bila emisi dibiarkan tinggi. PDB Asia-Pasifik berkembang diproyeksikan 17% lebih rendah pada 2070, dan hingga 300 juta orang terancam genangan pesisir ⚠︎.": "المسار إن تُركت الانبعاثات مرتفعة. يُتوقع أن يكون الناتج المحلي في آسيا والمحيط الهادئ النامية أقل بنسبة 17% بحلول 2070، مع تهديد الغمر الساحلي لما يصل إلى 300 مليون شخص ⚠︎.",
  "Tekanan harga pangan": "ضغط أسعار الغذاء",
  "poin persen / tahun": "نقطة مئوية / سنة",
  "Proyeksi 2035, rentang lintas skenario emisi (0,92 sampai 3,23). Bukan kepastian.": "إسقاط لعام 2035، نطاق عبر سيناريوهات الانبعاثات (0.92 إلى 3.23). ليس يقينًا.",
  "Adegan ilustrasi": "مشهد توضيحي",
