  "Pengukuran dan area lahan Anda tidak bisa dibaca admin Glyiv — itu ditegakkan aturan di server, bukan sekadar janji.": "لا يستطيع مشرفو Glyiv قراءة قياساتك ومساحات أرضك — وهذا مفروض بقواعد على الخادم، وليس مجرد وعد.",
  "Hubungi Kami — Glyiv": "اتصل بنا — Glyiv",
  "Satu alamat surel untuk semuanya, dan di halaman ini dijelaskan apa yang dijawab di mana — ralat artikel, permintaan data pribadi, dukungan aplikasi, dan urusan kemitraan.": "عنوان بريد إلكتروني واحد لكل شيء، وتشرح هذه الصفحة ما الذي يُجاب عنه وأين — تصحيح المقالات، وطلبات البيانات الشخصية، ودعم التطبيق، وشؤون الشراكات.",
  "Alamat surel kami": "عنوان بريدنا الإلكتروني",
