  "Identitas penerbit": "هوية الناشر",
  "Satu kotak masuk untuk redaksi, dukungan aplikasi, permintaan data pribadi, dan urusan bisnis. Tulis pokok persoalan di baris subjek supaya surat Anda sampai ke orang yang tepat lebih cepat.": "صندوق وارد واحد لهيئة التحرير، ودعم التطبيق، وطلبات البيانات الشخصية، والشؤون التجارية. اكتب صلب الموضوع في سطر الموضوع كي تصل رسالتك إلى الشخص المناسب أسرع.",
  "Kirim surel": "أرسل بريدًا إلكترونيًا",
  "Kami membalas dalam": "نردّ خلال",
  ". Kalau lewat dari itu, kirim ulang surat yang sama — kadang penyaring spam yang salah, bukan kami yang diam.": ". إن تجاوز ذلك، فأعد إرسال الرسالة نفسها — أحيانًا يكون الخطأ من مرشّح البريد المزعج، لا أننا صامتون.",
  "Kami tidak melayani pertanyaan lewat akun media sosial. Pesan yang masuk ke sana tidak tercatat, tidak bisa ditelusuri, dan tidak punya tenggat jawaban — jadi apa pun yang penting bagi Anda sebaiknya dikirim ke alamat surel di atas.": "لا نردّ على الأسئلة عبر حسابات التواصل الاجتماعي. الرسائل التي تصل هناك لا تُسجَّل، ولا يمكن تتبّعها، وليس لها موعد ردّ محدد — لذا فأي أمر يهمّك يُفضَّل إرساله إلى عنوان البريد الإلكتروني أعلاه.",
  "Redaksi": "التحرير",
  "Kalau sebuah angka, tanggal, atau kutipan di Glyiv News keliru, beri tahu kami dan sebutkan": "إذا كان رقم أو تاريخ أو اقتباس في Glyiv News خاطئًا، فأخبرنا واذكر",
  "judul artikelnya": "عنوان المقال",
  ". Ralat yang terbukti diperbaiki di badan artikel, dan perbaikannya dicatat.": ". التصحيح الذي تثبت صحته يُجرى في متن المقال، ويُسجَّل التصحيح.",
  "Yang membantu kami bergerak cepat: judul artikel, kalimat yang Anda persoalkan, dan — kalau ada — tautan ke dokumen yang menurut Anda benar. Setiap artikel Glyiv News mencantumkan daftar sumbernya di bagian bawah, jadi biasanya perselisihan bisa diselesaikan dengan membandingkan dokumen, bukan pendapat.": "ما يساعدنا على التحرّك بسرعة: عنوان المقال، والجملة التي تعترض عليها، و — إن وُجد — رابط إلى الوثيقة التي تراها صحيحة. كل مقال في Glyiv News يذكر قائمة مصادره في الأسفل، لذا يمكن عادةً حسم الخلاف بمقارنة الوثائق، لا الآراء.",
  "Prosedur ralat selengkapnya, susunan penanggung jawab, dan peran AI dalam penyusunan artikel dijelaskan di": "إجراءات التصحيح كاملةً، وتسلسل المسؤولية، ودور الذكاء الاصطناعي في إعداد المقالات، موضّحة في",
  "Redaksi & Kebijakan Editorial": "هيئة التحرير وسياسة التحرير",
  "Lapor": "إبلاغ",
  "Anda tidak perlu mengirim surel untuk melaporkan isi. Tombol": "لا حاجة لإرسال بريد إلكتروني للإبلاغ عن محتوى. زر",
  "ada di dalam setiap artikel, di bawah blok pengungkapan AI, dan juga di bilah atas mode Story. Tombol itu bekerja tanpa masuk akun dan tanpa keluar dari aplikasi.": "موجود داخل كل مقال، أسفل كتلة الإفصاح عن الذكاء الاصطناعي، وكذلك في الشريط العلوي لوضع Story. يعمل الزر دون تسجيل الدخول ودون مغادرة التطبيق.",
  "Laporan yang masuk lewat tombol itu tercatat beserta waktu servernya dan dibaca redaksi. Kalau Anda ingin jawaban tertulis atas laporan tersebut, kirim juga surel ke alamat di atas — formulir laporan sengaja tidak meminta identitas Anda, jadi kami tidak punya cara membalasnya.": "البلاغات الواردة عبر ذلك الزر تُسجَّل مع وقت الخادم وتقرأها هيئة التحرير. وإن أردت ردًا مكتوبًا على البلاغ، أرسل أيضًا بريدًا إلكترونيًا إلى العنوان أعلاه — نموذج البلاغ لا يطلب هويتك عمدًا، لذا لا نملك وسيلة للرد عليه.",
  "Permintaan salinan data, koreksi data, penarikan persetujuan, dan penghapusan akun dijawab lewat alamat surel yang sama. Sertakan alamat surel yang Anda pakai masuk, supaya kami bisa memastikan permintaan itu benar-benar datang dari pemilik akunnya.": "طلبات الحصول على نسخة من البيانات، وتصحيح البيانات، وسحب الموافقة، وحذف الحساب يُرَد عليها عبر عنوان البريد الإلكتروني نفسه. أرفق عنوان البريد الإلكتروني الذي تستخدمه لتسجيل الدخول، حتى نتمكن من التأكد من أن الطلب صادر فعلًا من صاحب الحساب.",
  "Menghapus akun bisa Anda lakukan sendiri tanpa menunggu kami: langkahnya ada di halaman": "يمكنك حذف حسابك بنفسك دون انتظارنا: الخطوات موجودة في صفحة",
